// Üretilen dosya: tool/ozgun/uret.py. Kimya · Kimyasal bağlar ve moleküller arası etkileşimler (orta).
const ozChemistry8Orta = <(String, String, List<String>, String)>[
  ('Hidrazin (H₂N–NH₂) molekülünde her azot atomu üzerinde kaç ortaklanmamış elektron çifti vardır?', '1', ['0', '2', '3'], 'Her azot iki hidrojen ve diğer azotla üç bağ yapar; beş değerlik elektronundan geriye bir ortaklanmamış çift kalır.'),
  ('Amid iyonu (NH₂⁻) için hangisi doğrudur?', 'Azotta iki ortaklanmamış çift vardır; iyon kırık doğru şeklindedir.', ['Azotta bir ortaklanmamış çift vardır; iyon amonyak gibi üçgen piramittir.', 'Azotta ortaklanmamış çift yoktur; iyon doğrusaldır.', 'Azotta üç ortaklanmamış çift vardır; iyon doğrusaldır.'], 'NH₂⁻ iyonunda 5 + 2 + 1 = 8 elektron vardır: iki bağ çifti ve iki ortaklanmamış çift. Dört elektron grubunun ikisi ortaklanmamış olduğundan şekil sudaki gibi açısaldır.'),
  ('Nitrozil iyonunun (NO⁺) en uygun Lewis yapısında azot ile oksijen arasındaki bağ hangisidir?', 'Üçlü bağ', ['Tekli bağ', 'İkili bağ', 'Yarım bağ'], 'NO⁺ iyonunda 5 + 6 − 1 = 10 elektron vardır; N₂ ile izoelektroniktir. Her iki atomun da oktetini tamamlaması için üçlü bağ ve her atomda birer ortaklanmamış çift gerekir.'),
  ('Siyanür iyonunun [:C≡N:]⁻ yapısında eksi formal yük hangi atom üzerindedir?', 'Karbon', ['Azot', 'İki atom arasında eşit bölünmüştür', 'Hiçbir atomda değildir'], 'Karbon: 4 − 2 − 3 = −1; azot: 5 − 2 − 3 = 0. Bu yüzden siyanür metal iyonlarına genellikle karbon ucundan bağlanır.'),
  ('Tetrafloroborat iyonunda (BF₄⁻) bor atomunun formal yükü kaçtır?', '−1', ['+1', '0', '+3'], 'Bor 3 değerlik elektronuna sahiptir, ortaklanmamış elektronu yoktur ve dört bağ yapar: 3 − 0 − 4 = −1. Florların formal yükü sıfırdır.'),
  ('Sülfat iyonu bütün S–O bağları tekli olacak biçimde çizilirse kükürdün formal yükü kaç olur?', '+2', ['0', '−2', '+6'], 'Dört tekli bağ yapan ve ortaklanmamış çifti olmayan kükürt için 6 − 0 − 4 = +2 bulunur. İki S=O bağı içeren yapıda bu değer sıfıra iner.'),
  ('Azot monoksit (NO) molekülü için hangisi doğrudur?', 'Toplam 11 değerlik elektronu olduğundan bir atom oktete ulaşamaz.', ['Toplam 10 değerlik elektronu vardır ve üçlü bağ içerir.', 'Bütün atomlar oktete ulaşır ve molekülde hiç eşleşmemiş elektron kalmaz.', 'Azot genişlemiş oktet yapar ve 10 elektron taşır.'], '5 + 6 = 11 tek sayıdır; eşleşmemiş bir elektron kalır. Bu yüzden NO bir radikaldir ve paramanyetiktir.'),
  ('Genişlemiş oktet neden azot, oksijen ve flor gibi 2. periyot elementlerinde görülmez?', 'Değerlik katmanlarında yalnız bir s ve üç p orbitali bulunduğu için', ['Elektronegatifliklerinin çok düşük olması nedeniyle bağ elektronlarını tutamamaları', 'Atom yarıçaplarının çok büyük olması nedeniyle', 'Yalnız iyonik bağ yapabildikleri için'], 'İkinci katmanda en fazla dört orbital ve sekiz elektron yer alabilir. Üçüncü ve daha sonraki periyotlarda atomlar büyüdükçe merkez atomun çevresine daha çok atom sığar ve sekizden fazla elektron yazılabilir.'),
  ('Aşağıdaki taneciklerden hangisinde merkez atomun çevresinde sekizden fazla elektron bulunur?', 'ICl₄⁻', ['NH₄⁺', 'BF₄⁻', 'CCl₄'], 'ICl₄⁻ iyonunda iyot dört bağ çifti ve iki ortaklanmamış çift, yani 12 elektron taşır. Diğer üç taneciğin merkez atomunda tam sekiz elektron bulunur.'),
  ('Nitrit iyonunda (NO₂⁻) iki N–O bağının uzunlukları deneysel olarak eşit bulunur. Her N–O bağının ortalama bağ derecesi kaçtır?', '1,5', ['1', '2', '4/3'], 'Nitrit için biri N=O, diğeri N–O olan iki eşdeğer rezonans yapısı yazılır. Bir π bağı iki bağa yayıldığından bağ derecesi (2 + 1)/2 = 1,5 olur.'),
  ('Rezonans yapıları birbirinden hangi bakımdan farklı olabilir?', 'Yalnızca π ve ortaklanmamış elektronların yerleşimi', ['Atom çekirdeklerinin uzaydaki konumları ve aralarındaki uzaklıklar', 'Molekülün toplam elektron sayısı', 'Atomların birbirine bağlanma sırası'], 'Rezonans yapılarında atom iskeleti aynı kalır; yalnızca elektronların yazılış yeri değişir. Atomların yeri değişirse bu artık rezonans değil, farklı bir moleküldür (izomer).'),
  ('Rezonans melezinin (gerçek yapının) enerjisi, yazılabilen tek tek rezonans yapılarının enerjisiyle karşılaştırıldığında nasıldır?', 'Herhangi bir rezonans yapısından daha düşüktür.', ['En kararsız rezonans yapısıyla aynıdır.', 'Rezonans yapılarının en yükseğinden de yüksektir.', 'Rezonans yapılarının aritmetik ortalamasına eşittir.'], 'Elektronların daha geniş bir bölgeye yayılması (delokalizasyon) sistemi kararlı kılar. Gerçek molekül, kâğıt üzerindeki her bir yapıdan daha düşük enerjilidir; aradaki farka rezonans enerjisi denir.'),
  ('Kükürt trioksit (SO₃) her atomun oktette olduğu bir S=O ve iki S–O bağıyla çizildiğinde kaç eşdeğer rezonans yapısı yazılabilir?', '3', ['2', '1', '4'], 'İkili bağ üç oksijenden herhangi birine yazılabilir; bu yüzden üç eşdeğer yapı vardır ve gerçekte üç bağ eşittir.'),
  ('Asetat iyonundaki (CH₃COO⁻) iki karbon–oksijen bağı için hangisi doğrudur?', 'Eşit uzunluktadır ve bağ dereceleri 1,5\'tir.', ['Biri ikili, diğeri tekli bağ olarak ayrı uzunluktadır.', 'İkisi de ikili bağdır, eksi yük karbondadır.', 'İkisi de tekli bağdır, eksi yük metil grubundadır.'], 'Eksi yük ve π bağı iki oksijen arasında rezonansla paylaşılır. Bu nedenle iki C–O bağı eşdeğerdir ve uzunlukları tekli ile ikili bağ arasındadır.'),
  ('Borohidrür iyonu (BH₄⁻) hangi molekülle izoelektroniktir ve şekli nedir?', 'CH₄; düzgün dörtyüzlü', ['NH₃; üçgen piramit', 'BF₃; üçgen düzlem', 'H₂O; kırık doğru'], 'BH₄⁻ iyonunda 3 + 4 + 1 = 8 değerlik elektronu vardır, tıpkı metan gibi. Dört bağ çifti olan bor dörtyüzlü bir düzen kurar.'),
  ('Nitronyum iyonu (NO₂⁺) için hangisi doğrudur?', 'Doğrusaldır ve CO₂ ile izoelektroniktir.', ['Kırık doğrudur ve O₃ ile izoelektroniktir.', 'Üçgen düzlemdir ve NO₃⁻ ile izoelektroniktir.', 'Doğrusaldır ve NO₂ ile izoelektroniktir.'], 'NO₂⁺ iyonunda 5 + 12 − 1 = 16 değerlik elektronu vardır. İki N=O bağı bulunan ve azotta ortaklanmamış çift taşımayan iyon CO₂ gibi doğrusaldır.'),
  ('Karbonat (CO₃²⁻) üçgen düzlem, sülfit (SO₃²⁻) ise üçgen piramit şeklindedir. Bu farkın nedeni nedir?', 'Sülfitte kükürt üzerinde bir ortaklanmamış çift bulunması', ['Kükürdün karbondan daha az elektronegatif olması', 'Sülfitte oksijen atomlarının hiç ortaklanmamış çift taşımaması', 'Karbonatın daha fazla oksijen içermesi'], 'Karbonatta karbon üç elektron grubuna sahiptir. Sülfitte kükürt üç bağın yanında bir ortaklanmamış çift taşır; dört grup dörtyüzlü dağılır ve atomlar piramit oluşturur.'),
  ('Amonyum sülfat [(NH₄)₂SO₄] katısında aşağıdaki bağ türlerinden hangisi bulunmaz?', 'Metalik bağ', ['İyonik bağ', 'Polar kovalent bağ', 'Koordine kovalent bağ'], 'NH₄⁺ ve SO₄²⁻ iyonları arasında iyonik bağ, iyonların içinde polar kovalent bağlar vardır. NH₄⁺ oluşumundaki bağ koordine kovalenttir. Metal atomu olmadığından metalik bağ yoktur.'),
  ('Siyanat iyonu (OCN⁻) ile karbon dioksit molekülü için ortak olan özellik hangisidir?', 'Doğrusal yapıda ve 16 değerlik elektronlu olmaları', ['İkisinin de apolar olması', 'İkisinin de merkezdeki karbon üzerinde ortaklanmamış bir çift taşıması', 'İkisinin de yalnız tekli bağ içermesi'], 'OCN⁻ iyonu 6 + 4 + 5 + 1 = 16 elektronludur, CO₂ ile izoelektroniktir ve doğrusaldır. Ancak uçları farklı atomlar olduğundan CO₂\'nin aksine dipolleri dengelenmez.'),
  ('Hidronyum iyonu (H₃O⁺) hangi molekülle izoelektroniktir ve geometrisi nedir?', 'NH₃; üçgen piramit', ['CH₄; düzgün dörtyüzlü', 'H₂O; kırık doğru', 'BF₃; üçgen düzlem'], 'H₃O⁺ iyonunda 6 + 3 − 1 = 8 değerlik elektronu, üç bağ çifti ve bir ortaklanmamış çift vardır; bu düzen amonyakla aynıdır.'),
  ('Ozon molekülünün iki rezonans yapısı için hangisi doğrudur?', 'Her iki yapıda da merkez oksijenin formal yükü aynıdır.', ['Birinde ozon doğrusal, diğerinde kırık doğrudur.', 'Yapılardan birinde molekül 20 elektron içerir.', 'Yapılardan birinde merkez oksijen hiç ortaklanmamış elektron çifti taşımaz.'], 'İki yapı da O=O–O ve O–O=O biçimindedir; merkez oksijen iki yapıda da +1 formal yük taşır. Yalnızca π bağı ile eksi yükün yer aldığı uç oksijen değişir.'),
  ('Kükürt tetraflorür (SF₄) molekülünde kükürdün çevresinde dört bağ çifti ve bir ortaklanmamış çift vardır. Molekülün şekli hangisidir?', 'Tahterevalli', ['Düzgün dörtyüzlü', 'Kare düzlem', 'Üçgen piramit'], 'Beş elektron grubu üçgen çift piramit düzeninde dağılır. Ortaklanmamış çift ekvator konumuna yerleşince atomların oluşturduğu şekil tahterevalliye (bozulmuş dörtyüzlü) benzer.'),
  ('Brom pentaflorür (BrF₅) molekülünde bromun çevresinde beş bağ çifti ve bir ortaklanmamış çift bulunur. Molekülün şekli hangisidir?', 'Kare piramit', ['Üçgen çift piramit', 'Sekizyüzlü', 'Beşgen düzlem'], 'Altı elektron grubu sekizyüzlü düzende dağılır. Köşelerden biri ortaklanmamış çiftçe tutulduğundan beş flor atomu kare tabanlı bir piramit oluşturur.'),
  ('İyot heptaflorür (IF₇) molekülünde iyot yedi flor atomuna bağlıdır ve ortaklanmamış çifti yoktur. Molekülün geometrisi hangisidir?', 'Beşgen çift piramit', ['Sekizyüzlü', 'Kare antiprizma', 'Üçgen çift piramit'], 'Yedi elektron grubu için VSEPR\'in öngördüğü düzen beşgen çift piramittir: beş flor ekvator düzleminde, ikisi eksen üzerindedir.'),
  ('Ksenon diflorür (XeF₂) molekülünde ksenonun çevresinde iki bağ çifti ve üç ortaklanmamış çift vardır. Molekül hangi şekildedir?', 'Doğrusal', ['Kırık doğru', 'T şekli', 'Üçgen düzlem'], 'Beş elektron grubu üçgen çift piramit düzeninde dağılır; üç ortaklanmamış çift ekvator düzlemine yerleşir. İki flor eksen üzerinde karşılıklı kalır ve F–Xe–F açısı 180° olur.'),
  ('VSEPR gösterimi AX₂E olan bir molekülün şekli ve yaklaşık bağ açısı için hangisi doğrudur?', 'Kırık doğru, 120°\'den biraz küçük', ['Doğrusal, 180°', 'Kırık doğru, 109,5°\'ten biraz küçük', 'Üçgen düzlem, tam 120°'], 'Üç elektron grubu üçgen düzlem düzeninde dağılır; biri ortaklanmamış çift olduğu için şekil açısaldır ve çiftin itmesi açıyı 120°\'nin biraz altına düşürür. SO₂ ve SnCl₂ bu türdendir.'),
  ('ICl₂⁻ iyonunda iyot iki klora bağlıdır ve üç ortaklanmamış çift taşır. İyonun VSEPR gösterimi ve şekli hangisidir?', 'AX₂E₃, doğrusal', ['AX₂E₂, kırık doğru', 'AX₂E₃, kırık doğru', 'AX₂E, doğrusal'], 'İki bağ ve üç ortaklanmamış çift AX₂E₃ demektir. Üç çift ekvatorda toplanır, iki klor eksen üzerinde 180° açıyla kalır; XeF₂ ve I₃⁻ ile aynı türdür.'),
  ('Merkez atomu çevresinde altı elektron grubu bulunan ve bunlardan ikisi ortaklanmamış çift olan bir molekülde iki çift nasıl yerleşir?', 'Birbirine 180° karşıt konumlara', ['Birbirine 90° komşu konumlara', 'İkisi de aynı köşeye', 'Biri eksene, biri ekvatora, aralarında 120° olacak biçimde'], 'Sekizyüzlü düzende iki büyük ortaklanmamış çift birbirinden en uzak olan karşıt köşelere yerleşir. Kalan dört atom kare düzlem oluşturur (AX₄E₂).'),
  ('Fosforil klorür (POCl₃) molekülünde fosfor bir oksijen ve üç klora bağlıdır ve ortaklanmamış çifti yoktur. Fosforun çevresindeki geometri hangisidir?', 'Dörtyüzlü', ['Üçgen piramit', 'Kare düzlem', 'Üçgen çift piramit'], 'Fosforun çevresinde dört bağ (dört elektron grubu) vardır ve ortaklanmamış çift yoktur. P=O ikili bağı VSEPR\'de tek grup sayıldığından düzen dörtyüzlüdür; bağlı atomlar farklı olduğu için açılar biraz bozulur.'),
  ('Kükürt dioksit ile karbon disülfür (CS₂) molekülleri arasında şekil bakımından fark olmasının nedeni nedir?', 'SO₂\'de kükürdün ortaklanmamış çift taşıması, CS₂\'de karbonun taşımaması', ['CS₂\'de daha fazla atom bulunması', 'Kükürdün karbondan daha elektronegatif olup bağları kendine çok daha fazla çekmesi', 'SO₂\'de yalnız tekli bağlar bulunması'], 'CS₂\'de karbon iki ikili bağ yapar ve ortaklanmamış çifti yoktur; doğrusaldır. SO₂\'de kükürt iki bağ grubuna ek olarak bir ortaklanmamış çift taşır ve molekül açısaldır.'),
  ('Kalay(II) klorürün gaz hâlindeki SnCl₂ molekülü için hangisi doğrudur?', 'Kalayda bir ortaklanmamış çift bulunduğundan açısaldır.', ['Kalayda ortaklanmamış çift bulunmadığından molekül doğrusaldır.', 'Kalay dört bağ yaptığından dörtyüzlüdür.', 'Kalay sp hibritleştiğinden doğrusaldır.'], 'Kalayın dört değerlik elektronundan ikisi bağ yapar, ikisi ortaklanmamış çift olarak kalır. Üç elektron grubu bulunan molekül AX₂E türündedir ve kırık doğru şeklindedir.'),
  ('Tionil klorür (SOCl₂) molekülünde kükürt bir oksijen, iki klora bağlıdır ve bir ortaklanmamış çift taşır. Molekülün şekli hangisidir?', 'Üçgen piramit', ['Üçgen düzlem', 'T şekli', 'Düzgün dörtyüzlü'], 'Kükürt çevresinde üç bağ grubu ve bir ortaklanmamış çift vardır. Dört grup dörtyüzlü dağılır, üç atom ise piramit oluşturur.'),
  ('XeOF₄ molekülünde ksenon bir oksijen ve dört flora bağlıdır ve bir ortaklanmamış çift taşır. Molekülün şekli hangisidir?', 'Kare piramit', ['Üçgen çift piramit', 'Sekizyüzlü', 'Tahterevalli'], 'Ksenon çevresinde beş bağ grubu ve bir ortaklanmamış çift, toplam altı grup vardır. Bu, BrF₅ gibi AX₅E türüdür ve kare piramit verir.'),
  ('VSEPR kuramına göre elektron grupları arasındaki itme büyükten küçüğe nasıl sıralanır?', 'Ortaklanmamış–ortaklanmamış > ortaklanmamış–bağ > bağ–bağ', ['Bağ–bağ > ortaklanmamış–bağ > ortaklanmamış–ortaklanmamış', 'Ortaklanmamış–bağ > ortaklanmamış–ortaklanmamış > bağ–bağ', 'Bütün itmeler eşit büyüklüktedir; yalnız grup sayısı önemlidir.'], 'Ortaklanmamış çift yalnız bir çekirdeğe bağlı olduğundan merkez atom çevresinde daha geniş yer kaplar. Bu yüzden çiftlerin itmesi en güçlüdür ve bağ açılarını daraltır.'),
  ('Kükürt hekzaflorürde (SF₆) kükürdün hibritleşmesi ve hibrit orbital sayısı hangisidir?', 'sp³d², 6 orbital', ['sp³d, 5 orbital', 'sp³, 4 orbital', 'sp³d², 8 orbital'], 'Altı flor atomuna yönelen altı eşdeğer orbital, bir s, üç p ve iki d orbitalinin karışmasıyla oluşur. Hibrit orbital sayısı karışan orbital sayısına eşittir.'),
  ('Ksenon tetraflorürde (XeF₄) ksenonun hibritleşmesi hangisidir?', 'sp³d²', ['sp³', 'dsp²', 'sp³d'], 'Ksenonun çevresinde dört bağ çifti ve iki ortaklanmamış çift olmak üzere altı elektron grubu vardır; altı hibrit orbital sp³d² hibritleşmesine karşılık gelir.'),
  ('Hibrit orbitaller bir molekülde genellikle hangi amaçla kullanılır?', 'σ bağı kurmak ya da ortaklanmamış çift taşımak için', ['Yalnız π bağı kurmak için', 'Yalnız iç katman elektronlarını tutmak ve bağ dışı bırakmak için', 'Molekülün manyetik özelliğini belirlemek için'], 'Hibrit orbitaller bağ yönünde uzandığından uç uca örtüşerek σ bağı oluşturur ya da ortaklanmamış çiftleri barındırır. π bağları hibritleşmeye katılmayan p orbitallerinden oluşur.'),
  ('Akrilonitril (CH₂=CH–C≡N) molekülündeki bütün bağlar σ ve π türlerine ayrılırsa dağılım nasıl olur?', '6 sigma, 3 pi', ['5 sigma, 3 pi', '6 sigma, 2 pi', '7 sigma, 2 pi'], 'Üç C–H, bir C–C, C=C\'nin σ\'sı ve C≡N\'nin σ\'sı toplam altı σ eder. C=C bir, C≡N iki π bağı içerir; toplam üç π vardır.'),
  ('Benzen (C₆H₆) molekülünde Kekulé yapısına göre kaç sigma ve kaç pi bağı vardır?', '12 sigma, 3 pi', ['6 sigma, 6 pi', '9 sigma, 3 pi', '12 sigma, 6 pi'], 'Altı C–C ve altı C–H bağının her biri bir σ içerir: 12 σ. Halkadaki üç ikili bağ üç π bağı verir.'),
  ('HCl molekülündeki bağ, değerlik bağı kuramına göre hangi orbitallerin örtüşmesiyle oluşur?', 'H\'nin 1s ve Cl\'nin 3p orbitali', ['H\'nin 1s ve Cl\'nin 3s orbitali', 'H\'nin 2p ve Cl\'nin 3p orbitali', 'İki atomun 1s orbitalleri'], 'Hidrojenin tek elektronu 1s\'te, klorun eşleşmemiş elektronu 3p orbitalindedir. Bu iki yarı dolu orbitalin uç uca örtüşmesi s–p türünde bir σ bağı verir.'),
  ('Değerlik bağı kuramına göre iki atom arasında kovalent bağ oluşması için hangi koşul gereklidir?', 'Zıt spinli birer elektron taşıyan orbitallerin örtüşmesi', ['Aynı spinli iki elektronun aynı orbitale girmesi', 'Atomlardan birinin elektronunu tamamen diğerine vermesi ve iyonların çekişmesi', 'İki atomun iç katman orbitallerinin karışması'], 'Kurama göre yarı dolu iki orbital örtüşür, iki elektron zıt spinlerle aynı bölgeyi paylaşır ve iki çekirdek arasında elektron yoğunluğu artar.'),
  ('Genel olarak σ bağının π bağından daha güçlü olmasının nedeni nedir?', 'Uç uca örtüşmede örtüşme bölgesinin daha büyük olması', ['σ bağında daha fazla elektron bulunması', 'π bağının yalnız iyonik bileşiklerde oluşması', 'σ bağında elektronların çekirdeklerden uzakta toplanması'], 'σ bağında elektron yoğunluğu doğrudan iki çekirdek arasında, bağ ekseni üzerinde toplanır ve örtüşme fazladır. π bağında örtüşme eksenin altında ve üstünde kalan daha küçük bir bölgededir.'),
  ('Azot molekülünde (N₂) iki atom arasındaki bağlar hangi orbitallerden oluşur?', 'Bir σ uç uca, iki π yan yana p–p örtüşmesiyle', ['Üç σ bağı da uç uca p–p örtüşmesiyle', 'Bir σ s–s, iki π s–p örtüşmesiyle', 'İki σ ve bir π bağı, üçü de p–p örtüşmesiyle'], 'Her azotun üç yarı dolu 2p orbitali vardır. Bağ eksenindeki p orbitalleri uç uca örtüşüp bir σ bağı, eksene dik iki p orbital çifti yan yana örtüşüp iki π bağı oluşturur.'),
  ('İki hidrojen atomu birbirine yaklaşırken çizilen potansiyel enerji–uzaklık eğrisinde en düşük enerjili noktaya karşılık gelen uzaklık neyi verir?', 'Bağ uzunluğunu', ['Atomların van der Waals yarıçaplarının toplamını', 'İyonlaşma enerjisini', 'Molekülün dipol momentini'], 'Çekme ile itmenin dengelendiği uzaklıkta enerji en düşüktür; moleküldeki çekirdekler arası denge uzaklığı, yani bağ uzunluğu budur. Eğrinin bu noktadaki derinliği bağ enerjisini verir.'),
  ('Bağ oluşturan iki atom denge uzaklığından daha fazla yaklaştırılırsa sistemin enerjisi hızla artar. Bunun başlıca nedeni nedir?', 'Çekirdekler arasındaki itmenin baskın hâle gelmesi', ['Elektronların çekirdeğe düşmesi', 'Ortak elektron çiftinin bağdan ayrılıp atomlara geri dönmesi', 'Atomların iyonlaşarak zıt yük kazanması'], 'Çok kısa uzaklıklarda artı yüklü çekirdeklerin ve iç elektronların itmesi, elektron–çekirdek çekimini aşar. Eğrinin sol kolu bu yüzden dik biçimde yükselir.'),
  ('He₂ molekülünün kararlı olarak bulunmamasını molekül orbital kuramı nasıl açıklar?', 'Bağ ve karşıt bağ orbitalleri ikişer elektron taşır; bağ derecesi sıfırdır.', ['Helyum atomlarının elektronegatifliği çok yüksek olduğu için', 'Helyum elektronlarının bağ yapan orbitale girememesi ve dördünün de karşıt bağda kalması', 'He₂\'de bağ derecesi 2 olup molekül fazla gergin olduğu için'], 'Dört elektronun ikisi σ1s bağ yapan, ikisi σ*1s karşıt bağ orbitaline girer: (2 − 2)/2 = 0. Net bir bağ oluşmaz.'),
  ('H₂⁺ iyonunun bağ derecesi kaçtır?', '0,5', ['1', '0', '1,5'], 'H₂⁺\'da tek elektron vardır ve σ1s bağ yapan orbitaline girer: (1 − 0)/2 = 0,5. Bağ zayıftır ama vardır; iyon gaz fazında gözlenmiştir.'),
  ('Karşıt bağ (antibağ) molekül orbitalinin ayırt edici özelliği hangisidir?', 'Çekirdekler arasında elektron yoğunluğunun sıfır olduğu düğüm bulunması', ['Çekirdekler arasındaki elektron yoğunluğunu iki atomdan daha fazla artırması', 'Enerjisinin bağ yapan orbitalden daha düşük olması', 'Yalnız iç katman elektronlarından oluşması'], 'Karşıt bağ orbitalinde atom orbitallerinin dalga fonksiyonları birbirini iki çekirdeğin arasında söndürür. Elektronu bu orbitalde olan molekül, ayrık atomlara göre kararsızlaşır.'),
  ('Aşağıdaki taneciklerden hangisi paramanyetiktir?', 'NO', ['N₂', 'CO', 'CN⁻'], 'NO 11 değerlik elektronludur ve bir elektronu π* orbitalinde eşleşmemiş kalır. N₂, CO ve CN⁻ 10 elektronlu, bütün elektronları eşleşmiş taneciklerdir.'),
  ('F₂ ile Ne₂ karşılaştırıldığında hangisi doğrudur?', 'F₂\'nin bağ derecesi 1\'dir; Ne₂\'de net bağ oluşmaz.', ['İkisinin de bağ derecesi 1\'dir.', 'F₂\'nin bağ derecesi 2, Ne₂\'ninki 1\'dir.', 'İkisinde de karşıt bağ orbitalleri tamamen boş kalır ve bağ oluşur.'], 'F₂\'de π* orbitalleri dolu, σ*2p boştur: (8 − 6)/2 = 1. Ne₂\'de iki elektron daha σ*2p\'ye girer ve bağ derecesi sıfıra iner.'),
  ('Molekül orbital kuramının Lewis kuramına göre üstün yanlarından biri hangisidir?', 'Kesirli bağ derecelerini ve manyetik özellikleri açıklayabilmesi', ['Molekülün üç boyutlu şeklini doğrudan vermesi', 'Hesap gerektirmeden her molekülü tek bir yapıyla göstermesi', 'Elektronları her zaman yalnızca belirli iki atom arasına yerleştirip sabitlemesi'], 'MO kuramı elektronları bütün moleküle yayılmış orbitallere yerleştirir. Bu sayede H₂⁺ gibi tek elektronlu bağları, O₂\'nin paramanyetizmasını ve 2,5 gibi kesirli bağ derecelerini açıklar.'),
  ('Be₂ molekülünün normal koşullarda kararlı bir molekül olarak bulunmaması MO kuramıyla nasıl açıklanır?', 'σ2s ve σ*2s orbitallerinin dolu olup bağ derecesinin sıfır olması', ['Berilyumun yalnız iyonik bağ yapabilmesi', 'Berilyum atomlarının çok büyük olması nedeniyle orbitallerinin hiç örtüşememesi', 'π orbitallerinin boş kalıp bağ derecesinin 3 olması'], 'İki berilyum dört değerlik elektronu getirir; ikisi bağ yapan, ikisi karşıt bağ orbitaline girer. Bağ derecesi (2 − 2)/2 = 0 olduğundan kararlı molekül beklenmez.'),
  ('Karbon monoksit ile N₂ molekül orbital diyagramı bakımından benzerdir. CO\'nun bağ derecesi ve manyetik özelliği nedir?', '3; diamanyetik', ['2; paramanyetik', '2,5; paramanyetik', '3; paramanyetik'], 'CO 10 değerlik elektronludur, N₂ ile izoelektroniktir. Sekiz bağ yapan ve iki karşıt bağ elektronu bağ derecesini 3 yapar; bütün elektronlar eşleşmiştir.'),
  ('NaCl için veriler (kJ/mol): Na süblimleşmesi +107, Na iyonlaşma enerjisi +496, ½ Cl₂ ayrışması +122, Cl elektron ilgisi −349, NaCl(k) oluşum entalpisi −411. Buna göre NaCl\'nin örgü enerjisi yaklaşık kaç kJ/mol\'dür?', '787', ['411', '376', '1133'], 'Örgü enerjisi U = 107 + 496 + 122 − 349 − (−411) = 787 kJ/mol bulunur. Gaz iyonlarından katı oluşurken bu kadar enerji açığa çıkar.'),
  ('NaCl\'nin Born-Haber döngüsünde Cl₂ molekülünün bağ ayrışma enerjisinin tamamı değil yarısı kullanılır. Bunun nedeni nedir?', 'Bir formül biriminde yalnız bir klor atomu bulunması', ['Klor molekülünün yalnız yarısının gaz hâlinde olması', 'Bağ enerjisinin yarısının elektron ilgisiyle geri kazanılması', 'Cl–Cl bağının yalnız bir elektron içeren yarım bir bağ olması'], 'Bir mol NaCl için bir mol Cl atomu, yani yarım mol Cl₂ gerekir. Bu yüzden döngüde ½ Cl₂(g) → Cl(g) basamağı yazılır ve Cl–Cl bağ enerjisinin yarısı kullanılır.'),
  ('Sodyum ve klordan katı NaCl oluşumunun Born-Haber basamaklarından hangisi enerji açığa çıkarır?', 'Klor atomunun elektron alması', ['Katı sodyumun süblimleşmesi', 'Sodyum atomunun iyonlaşması', 'Cl₂ molekülünün atomlarına ayrışması'], 'Süblimleşme, iyonlaşma ve bağ ayrışması enerji ister. Klorun elektron alması ve gaz iyonlarının örgüye dizilmesi ise ekzotermiktir.'),
  ('Sodyum atomunun iyonlaşması enerji gerektirdiği hâlde sodyum ile klorun NaCl oluşturması neden çok ekzotermiktir?', 'Zıt yüklü iyonların örgüye dizilirken çok büyük enerji açığa çıkarması', ['Sodyumun iyonlaşmasının aslında enerji açığa çıkarması', 'Klor molekülünün ayrışmasının enerji açığa çıkarması', 'NaCl\'de iki atom arasında çok sayıda ortak elektron çiftinin bulunması ve bunların enerji vermesi'], 'Na⁺ ve Cl⁻ iyonlarının oluşumu toplamda enerji ister. Ancak bu iyonların kristal örgüde bir araya gelmesiyle açığa çıkan örgü enerjisi bu maliyeti fazlasıyla karşılar.'),
  ('NaCl₂ bileşiğinin oluşmamasının temel nedeni hangisidir?', 'İkinci elektronun Na⁺ iyonunun iç katmanından koparılması gerekmesi', ['Klorun sodyumla yalnız kovalent bağ yapabilmesi', 'Sodyumun ikinci elektron ilgisinin çok yüksek olması ve klorun elektron verememesi', 'Na²⁺ iyonunun soy gaz düzenine ulaşması nedeniyle'], 'Na⁺ neon düzenindedir; ikinci elektron 2p katmanından koparılır ve bunun için gereken enerji (yaklaşık 4560 kJ/mol) hiçbir örgü kazancıyla karşılanamaz.'),
  ('İyonik bağın kovalent bağdan önemli bir farkı, yönsüz olmasıdır. Bu ne anlama gelir?', 'Bir iyon, çevresindeki bütün zıt yüklü iyonları her yönde çeker.', ['İyonik bağ yalnız iki iyon arasında, belirli bir eksende oluşur.', 'İyonik bağın uzunluğu her zaman sıfıra yakındır.', 'İyonlar örgüde belirli bir düzen olmadan gelişigüzel biçimde dağılır.'], 'Elektrostatik çekim küresel simetriktir. Bu nedenle bir Na⁺ iyonu tek bir Cl⁻ ile değil, çevresindeki altı Cl⁻ iyonuyla eşit biçimde etkileşir.'),
  ('Kovalent bileşiklerin belirli molekül şekillerine (açısal, piramit, dörtyüzlü gibi) sahip olmasının temel nedeni hangisidir?', 'Kovalent bağların belirli yönlerde uzanan orbitallerle kurulması', ['Kovalent bağların her yönde eşit etki eden elektrostatik çekimle kurulması', 'Molekül şeklinin yalnız atomların kütlesiyle belirlenmesi', 'Kovalent bileşiklerin her zaman kristal örgü oluşturması'], 'Kovalent bağda elektron yoğunluğu iki çekirdek arasındaki belirli bir doğrultuda toplanır; bu nedenle bağlar arasında belirli açılar oluşur. İyonik çekim ise yönsüzdür ve ayrık molekül şekli vermez.'),
  ('Lityum florürün (LiF) erime noktası sezyum iyodürünkünden (CsI) çok daha yüksektir. Bunun en iyi açıklaması hangisidir?', 'Küçük iyonların birbirine yakın durup daha güçlü çekilmesi', ['LiF\'nin kovalent ağ yapısında olması', 'CsI\'da iyonların daha büyük yük taşıması', 'Lityumun sezyumdan daha ağır bir metal olması ve daha yoğun örgü kurması'], 'İki bileşikte de yükler +1 ve −1\'dir. LiF\'de iyonlar çok küçük olduğundan birbirine yakın durur ve örgü daha sıkı tutunur; erime için daha fazla enerji gerekir.'),
  ('Al₂O₃\'ün örgü enerjisinin MgO\'nunkinden de büyük olmasının başlıca nedeni hangisidir?', 'Al³⁺ iyonunun hem daha yüklü hem de daha küçük olması', ['Al₂O₃\'te iyonların hiç yük taşımaması', 'Oksijenin Al₂O₃\'te farklı bir yük taşıması', 'Alüminyum atomunun magnezyumdan daha büyük olması ve oksijeni sıkı sarması'], 'İki bileşikte de anyon O²⁻\'dir. Al³⁺ hem daha yüklü hem de Mg²⁺\'dan küçüktür; bu iki etki çekimi artırır. Al₂O₃\'ün (korundum) çok sert ve yüksek erime noktalı olması buna dayanır.'),
  ('Çinko sülfürün çinko blendi yapısında her Zn²⁺ iyonu kaç S²⁻ iyonuyla, hangi düzende çevrilidir?', '4 iyonla, dörtyüzlü düzende', ['6 iyonla, sekizyüzlü düzende', '8 iyonla, küp düzeninde', '2 iyonla, doğrusal düzende'], 'Çinko blendinde koordinasyon sayısı 4 : 4\'tür; her iyon dört zıt yüklü iyonla dörtyüzlünün köşelerinde çevrilidir. Bu düzen elmas yapısına benzer.'),
  ('Kalsiyum florür (florit, CaF₂) kristalinde her Ca²⁺ sekiz F⁻ ile çevrilidir. Her F⁻ iyonu kaç Ca²⁺ ile çevrilidir?', '4', ['8', '2', '6'], 'Formülde iki F⁻ başına bir Ca²⁺ vardır; bu yüzden anyonun koordinasyon sayısı katyonunkinin yarısıdır: 8 : 4.'),
  ('Fajans kurallarına göre iyonik bir bileşikte kovalent karakter hangi durumda artar?', 'Katyon küçük ve çok yüklü, anyon büyük olduğunda', ['Katyon büyük ve az yüklü, anyon küçük olduğunda', 'İki iyonun da büyük ve tek yüklü olduğu durumda', 'Anyon küçük, katyon büyük ve tek yüklü olduğunda'], 'Küçük, yüksek yüklü bir katyon güçlü bir elektrik alanı yaratır ve büyük anyonun elektron bulutunu kendine doğru çarpıtır (kutuplar). Elektronların paylaşılmaya başlaması kovalent karakter demektir.'),
  ('Bir anyonun \'kutuplanabilirliği\' neyi ifade eder?', 'Elektron bulutunun bir elektrik alanında kolayca çarpıtılabilmesini', ['Anyonun kendi başına kalıcı bir dipol taşımasını', 'Anyonun suda kolayca çözünebilmesini', 'Anyonun çevresindeki katyonları elektron bulutuyla itebilmesini ve uzaklaştırmasını'], 'Büyük anyonlarda dış elektronlar çekirdekten uzaktadır ve gevşek tutulur; yakındaki bir katyonun alanı bulutu kolayca bozar. I⁻, F⁻\'den çok daha kutuplanabilirdir.'),
  ('Pauling elektronegatiflik değerleri C = 2,55 ve H = 2,20 olduğuna göre C–H bağında kısmi yükler nasıl dağılır?', 'Karbon kısmi eksi, hidrojen kısmi artı yüklüdür.', ['Karbon kısmi artı, hidrojen kısmi eksi yüklüdür.', 'İki atom da eşit kısmi eksi yük taşır.', 'Bağda kesinlikle hiçbir yük ayrımı olmaz.'], 'Ortak elektronlar daha elektronegatif olan karbona biraz yakın durur. Fark yalnız 0,35 olduğundan polarlık çok azdır ama yön karbonun eksi ucu olmasıdır.'),
  ('Elektronegatiflik değerleri Si = 1,90 ve H = 2,20 olduğuna göre silan (SiH₄) molekülündeki Si–H bağları için hangisi doğrudur?', 'Hidrojen kısmi eksi, silisyum kısmi artı yüklüdür.', ['Hidrojen kısmi artı, silisyum kısmi eksi yüklüdür.', 'Bağ tamamen iyonik olup H⁺ iyonları içerir.', 'Silisyum genişlemiş oktetle bağları apolar kılar.'], 'Silisyum hidrojenden daha az elektronegatiftir; bu nedenle bağ elektronları hidrojene kayar. Bu, metandaki C–H bağının tersidir.'),
  ('Pauling değerleri P = 2,19 ve H = 2,20 olduğuna göre fosfindeki (PH₃) P–H bağları için en doğru nitelendirme hangisidir?', 'Neredeyse apolar kovalent', ['Belirgin biçimde polar kovalent', 'Ağırlıklı olarak iyonik', 'Koordine kovalent ve iyonik karışımı'], 'Elektronegatiflik farkı yalnızca 0,01\'dir. Ortak elektronlar iki çekirdek arasında hemen hemen eşit paylaşıldığından bağ pratikte apolardır.'),
  ('Elektronegatiflikleri N = 3,04 ve Cl = 3,16 olan azot triklorürde (NCl₃) N–Cl bağları için hangisi doğrudur?', 'Çok az polardır; kısmi eksi uç klordadır.', ['Çok polardır; kısmi eksi uç azottadır.', 'İyonik bağdır; N³⁺ ve Cl⁻ iyonları vardır.', 'Tamamen apolardır; çünkü iki atom da ametaldir.'], 'Fark 0,12 gibi çok küçük bir değerdir; bağ hafif polardır ve elektronlar biraz daha elektronegatif olan klora kayar.'),
  ('Fosfor pentaklorür (PCl₅) molekülü polar P–Cl bağları içerir. Molekülün polarlığı için hangisi doğrudur?', 'Simetrik üçgen çift piramit olduğundan apolardır.', ['Beş bağ tek sayı olduğundan mutlaka polardır.', 'Fosforda ortaklanmamış çift bulunduğundan polardır.', 'Eksen bağları ekvatordakilerden farklı olduğu için polardır.'], 'Üç ekvator bağının dipolleri 120° aralıklarla birbirini, iki eksen bağının dipolleri de 180°\'de birbirini dengeler. Net dipol momenti sıfırdır.'),
  ('Kükürt tetraflorür (SF₄) molekülü için hangisi doğrudur?', 'Tahterevalli şekli nedeniyle dipolleri dengelenmez; polardır.', ['Dört özdeş bağ içerdiği için mutlaka apolardır.', 'Kare düzlem şeklinde olduğu ve dört flor karşılıklı durduğu için apolardır.', 'Kükürt ile flor arasındaki bağlar apolar olduğu için apolardır.'], 'Ekvatordaki ortaklanmamış çift simetriyi bozar; bağ dipollerinin vektör toplamı sıfır olmaz.'),
  ('Ksenon tetraflorür (XeF₄) iki ortaklanmamış çift taşıdığı hâlde apolardır. Bunun nedeni nedir?', 'Kare düzlemde karşılıklı bağ dipollerinin ve çiftlerin dengelenmesi', ['Xe–F bağlarının elektronegatiflik farkı olmadığı için apolar olması', 'Ksenonun soy gaz olması nedeniyle asla bağ dipolü oluşturamaması', 'Ortaklanmamış çiftlerin aynı yöne bakıp molekülü düzleştirmesi'], 'Dört flor karşılıklı ikişer çift oluşturur ve iki ortaklanmamış çift birbirine 180° karşıttır. Bütün etkiler simetrik olarak sıfırlanır.'),
  ('Ozon molekülü yalnız oksijen atomlarından oluştuğu hâlde küçük bir dipol momentine sahiptir. Bunun açıklaması hangisidir?', 'Açısal yapıda merkez ve uç oksijenlerin elektron yoğunluğunun farklı olması', ['Oksijen atomlarının farklı izotoplardan oluşması ve kütle farkının yük ayırması', 'Ozonun iyonik bir bileşik olması', 'Ozon moleküllerinin doğrusal olup π bağı taşıması'], 'Merkezdeki oksijen kısmi artı, uçlar kısmi eksi yük taşır (formal yükler de bunu gösterir). Molekül açısal olduğundan bu yük ayrımı net bir dipol oluşturur.'),
  ('Karbon disülfür (CS₂) ve hidrojen siyanür (HCN) ikisi de doğrusaldır. Polarlıkları için hangisi doğrudur?', 'CS₂ apolar, HCN polardır.', ['İkisi de doğrusal olduğu için apolardır.', 'CS₂ polar, HCN apolardır.', 'İkisi de karbon içerdiği için polardır.'], 'CS₂\'de iki özdeş C=S dipolü zıt yönde birbirini götürür. HCN\'de iki ucun atomları farklıdır; H–C ve C≡N dipolleri aynı yönde toplanır.'),
  ('1,2-diklorobenzen (orto) ile 1,4-diklorobenzen (para) karşılaştırıldığında hangisi doğrudur?', 'Orto izomer polar, para izomer apolardır.', ['İkisi de aynı formülde olduğundan polarlıkları eşittir.', 'Para izomer polar, orto izomer apolardır.', 'İkisi de halka yapısından dolayı apolardır.'], 'Para konumda iki C–Cl dipolü halkanın karşıt uçlarında zıt yönde durur ve birbirini götürür. Orto konumda dipoller 60° aralıkla toplanır ve net dipol oluşur.'),
  ('Klor triflorür (ClF₃) molekülünün polarlığı için hangisi doğrudur?', 'T şekli nedeniyle polardır.', ['Üçgen düzlem olduğundan apolardır.', 'Üç özdeş bağ dipolü birbirini götürdüğünden apolardır.', 'Klor ve flor aynı gruptan olduğu için bağları apolardır.'], 'İki ekvator çifti molekülü T biçimine sokar; ekvatordaki tek Cl–F dipolü dengelenmez ve net dipol oluşur.'),
  ('SF₆, XeF₂, CO₂ ve BrF₅ moleküllerinden hangisi polardır?', 'BrF₅', ['SF₆', 'XeF₂', 'CO₂'], 'SF₆ simetrik sekizyüzlü, XeF₂ ve CO₂ doğrusaldır; dipolleri dengelenir. BrF₅ kare piramittir; tepe ile taban arasındaki asimetri net bir dipol bırakır.'),
  ('Hidrojen peroksit (H₂O₂) molekülü için hangisi doğrudur?', 'Düzlemsel olmayan açık kitap biçimi nedeniyle polardır.', ['Simetrik doğrusal yapısı nedeniyle apolardır.', 'O–O bağı apolar olduğu için molekülün tamamı da apolar olmak zorundadır.', 'Dört atomu bir kare düzlem oluşturduğu için apolardır.'], 'Her oksijen sp³\'e benzer düzendedir ve iki O–H bağı farklı düzlemlerde yer alır. Bu düzlemsel olmayan yapıda O–H dipolleri birbirini götürmez.'),
  ('Klorometan (CH₃Cl) ve diklorometan (CH₂Cl₂) dipol momentleri ölçüldüğünde ikisi de sıfırdan farklı çıkar. Buna karşın tetraklorometanınki sıfırdır. Hangi genelleme bu verilerle uyumludur?', 'Dörtyüzlüde dört özdeş bağ olduğunda dipoller sıfırlanır.', ['Klor atomu sayısı arttıkça dipol momenti hep artar.', 'Karbon içeren her molekül apolar olur.', 'Dörtyüzlü moleküller bağlı atomlar ne olursa olsun her zaman polardır.'], 'Dörtyüzlü düzen yalnız dört bağın aynı olduğu durumda tam simetriktir. Bir ya da daha fazla bağ farklı olunca vektörler sıfıra inmez.'),
  ('Sodyum (98 °C), magnezyum (650 °C) ve alüminyumun (660 °C) erime noktalarının bu sırayla artmasının temel nedeni nedir?', 'Elektron denizine verilen değerlik elektronu sayısının artması', ['Atom yarıçaplarının periyot boyunca büyümesi ve atomların daha sıkı istiflenmesi', 'Bu metallerin giderek iyonik bağ yapmaya başlaması', 'Atom kütlesi arttıkça metalik bağın tamamen ortadan kalkması'], 'Na bir, Mg iki, Al üç değerlik elektronu verir; aynı zamanda katyonlar küçülür ve yükleri artar. Elektron denizi yoğunlaştıkça metalik bağ güçlenir.'),
  ('Tungsten, krom ve molibden gibi geçiş metallerinin erime noktalarının alkali metallere göre çok yüksek olması neyle açıklanır?', 'd elektronlarının da metalik bağa katılması', ['Bu metallerin moleküler kristal oluşturması', 'Geçiş metallerinde hiç serbest elektron bulunmaması', 'Bu metallerin atomları arasında hidrojen bağı bulunması'], 'Geçiş metallerinde s elektronlarına ek olarak d elektronları da delokalize olup bağlanmaya katkı yapar. Daha çok bağ elektronu daha güçlü metalik bağ demektir.'),
  ('Bant kuramına göre metallerin elektriği iyi iletmesinin nedeni nedir?', 'Değerlik bandının kısmen dolu olması ya da iletim bandıyla örtüşmesi', ['Değerlik bandı ile iletim bandı arasında çok geniş bir yasak aralık bulunması', 'Bütün elektronların iç katmanlarda sıkıca tutulması', 'Elektronların yalnız tek bir atomun orbitalinde kalması'], 'Kristaldeki çok sayıda atom orbitali birleşerek birbirine çok yakın enerji düzeylerinden oluşan bantlar verir. Metallerde boş düzeyler doluların hemen üstünde olduğundan küçük bir gerilim elektronları harekete geçirir.'),
  ('Bant kuramına göre elmasın elektriği iletmemesinin nedeni nedir?', 'Değerlik bandı ile iletim bandı arasındaki aralığın çok geniş olması', ['Elmasta değerlik bandının hiç bulunmaması ve elektronların çekirdekte toplanması', 'İletim bandının elektronlarla tamamen dolu olması', 'Elmas atomlarının iyonlarına ayrışmış olması'], 'Elmasın bant aralığı yaklaşık 5,5 eV\'tur. Oda sıcaklığındaki ısıl enerji elektronları bu aralıktan iletim bandına çıkaramaz; elmas yalıtkandır.'),
  ('Saf silisyuma az miktarda fosfor katılması hangi tür yarı iletken oluşturur ve neden?', 'n tipi; fosforun fazladan bir değerlik elektronu getirmesi', ['p tipi; fosforun bir elektron eksik getirmesi', 'n tipi; fosforun silisyumdan bir elektron alıp eksi yüklü iyona dönüşmesi', 'p tipi; fosforun silisyum bağlarını tamamen koparması'], 'Fosfor 5 değerlik elektronludur; dört Si ile bağ yaptıktan sonra bir elektron artar. Bu serbest elektronlar eksi yük taşıyıcısıdır ve malzeme n tipi olur.'),
  ('Silisyuma bor katılmasıyla elde edilen p tipi yarı iletkende akımı taşıyan başlıca yük taşıyıcısı hangisidir?', 'Elektron eksikliğinden doğan boşluklar', ['Bor atomlarının silisyum örgüsüne fazladan verdiği serbest elektronlar', 'Silisyum çekirdeklerinden kopan protonlar', 'Kristalde hareket eden B³⁺ iyonları'], 'Bor 3 değerlik elektronludur; dört komşu silisyumla bağ kurarken bir bağda elektron eksik kalır. Bu boşluğa komşu elektronların atlaması, artı yüklü bir taşıyıcının ilerlemesi gibi davranır.'),
  ('Saf silisyumun oda sıcaklığındaki elektriksel davranışını bant kuramı nasıl açıklar?', 'Bant aralığı küçük olduğundan az sayıda elektron iletim bandına geçer.', ['Bant aralığı sıfır olduğundan silisyum oda sıcaklığında metal kadar iyi iletir.', 'Bant aralığı çok büyük olduğundan hiç iletmez.', 'Değerlik bandı boş olduğundan yalnız ışıkta iletir.'], 'Silisyumun bant aralığı yaklaşık 1,1 eV\'tur. Bu küçük aralık nedeniyle bir miktar elektron iletim bandına çıkar; iletkenlik metallerden çok düşük ama yalıtkanlardan yüksektir.'),
  ('Çelikte karbon atomlarının demir örgüsündeki yerleşimi için hangisi doğrudur?', 'Küçük karbon atomları demir atomları arasındaki boşluklara yerleşir.', ['Karbon atomları demir atomlarının yerini alarak örgüde sıralanır.', 'Karbon demirle iyonik bileşik oluşturup ayrı bir faz olarak durur.', 'Karbon atomları örgünün dışında, yalnız metalin yüzeyinde birikir.'], 'Karbon demirden çok küçüktür ve örgü boşluklarına (ara yerlere) girer. Bu tür alaşıma ara yer alaşımı denir; boşluklardaki atomlar katmanların kaymasını zorlaştırıp metali sertleştirir.'),
  ('Kuvarsın (SiO₂) yapısında her silisyum ve her oksijen atomu kaç atoma bağlıdır?', 'Her Si dört O\'ya, her O iki Si\'ye', ['Her Si iki O\'ya, her O bir Si\'ye', 'Her Si altı O\'ya, her O üç Si\'ye', 'Her Si dört O\'ya, her O dört Si\'ye'], 'Kuvars, köşelerinden birbirine bağlı SiO₄ dörtyüzlülerinden oluşan bir ağdır. Her oksijen iki dörtyüzlüye ortak olduğundan oran Si : O = 1 : 2 olur.'),
  ('Bor nitrürün (BN) altıgen biçiminin \'beyaz grafit\' olarak anılmasının nedeni nedir?', 'Grafit gibi katmanlı olup kayganlaştırıcı özellik göstermesi', ['Grafit gibi elektriği çok iyi iletmesi', 'Yalnız karbon atomlarından oluşması', 'Elmas kadar sert olup kesici uçlarda ve aşındırıcılarda kullanılması'], 'Altıgen BN\'de B ve N atomları grafit benzeri düzlem katmanlar kurar; katmanlar zayıf kuvvetlerle tutunduğundan kayar. Ancak grafitin aksine elektriği iletmez ve beyazdır.'),
  ('Silisyum ve germanyum gibi yarı iletkenlerden yapılan güneş pillerinde ışığın elektrik üretmesi bant kuramıyla nasıl açıklanır?', 'Fotonların elektronları iletim bandına çıkarması', ['Işığın silisyum çekirdeklerini parçalaması', 'Fotonların kristaldeki protonları serbest bırakıp bunların akım taşıması', 'Işığın kristali eritip iyonlarını hareketlendirmesi'], 'Enerjisi bant aralığından büyük olan fotonlar elektron–boşluk çiftleri oluşturur. p–n eklemindeki iç elektrik alanı bu taşıyıcıları ayırarak dış devrede akım doğurur.'),
  ('Aseton (CH₃COCH₃, 58 g/mol) 56 °C\'de, bütan (C₄H₁₀, 58 g/mol) ise yaklaşık 0 °C\'de kaynar. Bu farkın en iyi açıklaması hangisidir?', 'Polar aseton molekülleri arasında dipol-dipol çekimi bulunması', ['Aseton molekülleri arasında güçlü hidrojen bağı bulunması', 'Bütan moleküllerinin aseton moleküllerinden daha polar olması', 'Bütanın aseton moleküllerinden çok daha fazla elektron içermesi ve bunları sıkı tutması'], 'Molekül kütleleri eşit olduğundan London kuvvetleri benzerdir. Asetonun C=O grubu kalıcı dipol oluşturur ve ek bir dipol-dipol çekimi sağlar. Asetonda O–H bulunmadığından kendi molekülleri arasında hidrojen bağı yoktur.'),
  ('Bir atomun ya da molekülün kutuplanabilirliği genellikle hangi durumda artar?', 'Elektron sayısı ve elektron bulutunun hacmi arttıkça', ['Elektronegatifliği arttıkça ve atom yarıçapı küçüldükçe', 'Molekülde ortaklanmamış çift kalmadığında', 'Molekül kütlesi azaldıkça'], 'Büyük bir elektron bulutunda dış elektronlar çekirdekten uzaktadır ve daha gevşek tutulur; dış etkilerle kolayca çarpıtılır. Kutuplanabilirlik arttıkça London kuvvetleri güçlenir.'),
  ('Oksijen gazının apolar olduğu hâlde suda az da olsa çözünmesini sağlayan etkileşim hangisidir?', 'Dipol-indüklenmiş dipol etkileşimi', ['İyon-dipol etkileşimi', 'Su ile oksijen arasında hidrojen bağı', 'Oksijenin sudaki H⁺ ile iyonik bağı'], 'Polar su molekülü yakınındaki O₂ molekülünün elektron bulutunu bozarak geçici bir dipol oluşturur (indükler). Bu zayıf çekim, sudaki yaşam için gerekli az miktardaki oksijenin çözünmesini sağlar.'),
  ('Tek tek etkileşimler ele alındığında aşağıdaki sıralamalardan hangisi genellikle doğrudur?', 'İyon-dipol > hidrojen bağı > dipol-dipol > London', ['London > dipol-dipol > hidrojen bağı > iyon-dipol', 'Hidrojen bağı > iyon-dipol > London > dipol-dipol', 'Dipol-dipol > iyon-dipol > hidrojen bağı > London'], 'Tam yük taşıyan iyonun kalıcı dipolle etkileşimi en güçlüdür. Hidrojen bağı, özel ve güçlü bir dipol-dipol etkileşimidir; tek bir London etkileşimi ise en zayıfıdır. Büyük moleküllerde toplam London katkısı yine de çok büyük olabilir.'),
  ('Helyumun kaynama noktasının (yaklaşık −269 °C) bütün maddeler içinde en düşük olmasının nedeni nedir?', 'İki elektronlu küçük atomunun kutuplanabilirliğinin çok düşük olması', ['Helyum atomlarının birbirini iterek aralarında asla çekim oluşmaması', 'Helyum atomları arasında hidrojen bağı bulunması', 'Helyumun çekirdeğinde nötron bulunmaması'], 'Helyum atomları arasında yalnız London kuvvetleri vardır. İki elektronu çekirdeğe çok sıkı bağlı olduğundan anlık dipoller son derece zayıftır ve atomları bir arada tutmak için çok düşük sıcaklık gerekir.'),
  ('CH₄, SiH₄, GeH₄ ve SnH₄ bileşiklerinin kaynama noktaları için hangisi doğrudur?', 'Molekül büyüdükçe düzenli olarak artar; en düşük CH₄\'tür.', ['CH₄ hidrojen bağı nedeniyle en yüksek kaynama noktasına sahiptir.', 'Molekül büyüdükçe düzenli olarak azalır.', 'Dördünün kaynama noktası aynıdır.'], '14. grup hidrürleri apolardır ve hidrojen bağı yapmaz. Yalnız London kuvvetleri etkili olduğundan elektron sayısı arttıkça kaynama noktası düzenli biçimde yükselir.'),
  ('H₂O, H₂S, H₂Se ve H₂Te arasında kaynama noktası en düşük olan hangisidir?', 'H₂S', ['H₂O', 'H₂Se', 'H₂Te'], 'Su hidrojen bağı nedeniyle grubun en yükseğidir. Geri kalan üçünde yalnız dipol-dipol ve London kuvvetleri etkilidir; bunlardan en küçük olan H₂S en düşük kaynama noktasına sahiptir.'),
  ('15., 16. ve 17. grupların hidrürlerinde ilk üyenin (NH₃, H₂O, HF) kaynama noktası beklenenden çok yüksektir; 14. grupta ise CH₄ için böyle bir sapma yoktur. Bunun nedeni nedir?', 'C–H bağı yeterince polar olmadığından CH₄\'ün hidrojen bağı yapamaması', ['Metanın molekül kütlesinin grubun en büyüğü olması ve buna karşın uçucu kalması', 'Metanın iyonik bir bileşik olması', 'CH₄\'te karbonun genişlemiş oktet yapması'], 'Hidrojen bağı için H\'nin N, O ya da F\'ye bağlı olması gerekir. C–H bağı yeterince polar değildir ve karbonda ortaklanmamış çift yoktur; bu yüzden CH₄ eğilimin en altında yer alır.'),
  ('Katı hidrojen florürde HF molekülleri nasıl bir düzen oluşturur?', 'Hidrojen bağlarıyla bağlanmış zikzak zincirler', ['Ayrı ayrı duran, birbirini hiç çekmeyen moleküller', 'Üç boyutlu iyonik bir H⁺F⁻ örgüsü', 'Dörtyüzlü düzende kovalent ağ yapısı'], 'Her HF molekülünün hidrojeni komşu molekülün florundaki çiftle hidrojen bağı yapar. F–H···F açısı yaklaşık 120° olduğundan zincir zikzak biçimindedir.'),
  ('Bir maddenin hem hidrojen bağı verici hem alıcı olabilmesi için hangi yapısal koşul gerekir?', 'N, O ya da F\'ye bağlı bir H ile bu atomlarda ortaklanmamış çift bulunması', ['Yalnız bir karbon zinciri içermesi', 'Molekülde hiç ortaklanmamış çift bulunmaması ve bütün elektronların bağlarda yer alması', 'Hidrojenin karbona bağlı olması'], 'Verici, elektronegatif bir atoma bağlı ve kısmi artı yüklü bir H sağlar. Alıcı ise bu H\'yi çeken bir ortaklanmamış çifttir. Su, alkoller ve aminler her iki rolü de üstlenebilir.'),
  ('o-Nitrofenol ile p-nitrofenol karışımı su buharı damıtmasıyla ayrıldığında hangisi buharla birlikte taşınır ve neden?', 'o-Nitrofenol; molekül içi hidrojen bağı onu daha uçucu kılar.', ['p-Nitrofenol; moleküller arası hidrojen bağı onu daha uçucu kılar.', 'p-Nitrofenol; molekülü daha küçük olduğu için daha kolay buharlaşır.', 'İkisi de eşit taşınır; çünkü aynı formüle sahiptirler.'], 'Molekül içi hidrojen bağı yapan orto izomerin moleküller arası çekimi zayıftır ve buhar basıncı yüksektir. Para izomer moleküller arası hidrojen bağlarıyla tutunduğundan geride kalır.'),
  ('Bir proteinin üçüncül yapısını oluşturan etkileşimlerden hangisi kovalent bir bağdır?', 'Sisteinler arasındaki disülfür köprüsü', ['Yan zincirler arasındaki tuz köprüsü', 'Apolar yan zincirlerin hidrofobik etkileşimi', 'Polar yan zincirler arasındaki hidrojen bağı'], 'Disülfür köprüsü (–S–S–), iki sistein kalıntısının kükürt atomları arasında kurulan kovalent bağdır. Diğer üç etkileşim kovalent olmayan zayıf etkileşimlerdir.'),
  ('Yumurta pişirildiğinde akının beyazlaşıp katılaşması (denatürasyon) sırasında genellikle hangi bağlar korunur?', 'Amino asitleri birbirine bağlayan peptit bağları', ['Zincir kıvrımlarını tutan hidrojen bağları', 'Yan zincirler arasındaki tuz köprüleri', 'Apolar gruplar arasındaki hidrofobik etkileşimler'], 'Isı, proteinin şeklini koruyan zayıf etkileşimleri bozar ve zincir açılır. Kovalent peptit bağları kopmaz; bu nedenle birincil yapı (amino asit dizisi) değişmez.'),
  ('DNA çift sarmalının kararlılığına, baz çiftleri arasındaki hidrojen bağlarının yanında hangi etkileşim de önemli katkı yapar?', 'Üst üste dizilen düzlemsel bazlar arasındaki istiflenme etkileşimleri', ['Komşu fosfat grupları arasındaki güçlü iyonik çekim ve bunların birbirini tutması', 'Şeker halkaları arasındaki kovalent bağlar', 'Bazlar ile su arasındaki iyonik bağlar'], 'Düzlemsel aromatik bazlar sarmal boyunca birbirinin üzerine istiflenir; aralarındaki van der Waals ve π etkileşimleri sarmalı önemli ölçüde kararlı kılar. Eksi yüklü fosfatlar ise birbirini iter.'),
  ('Sıvı sudaki hidrojen bağları için hangisi doğrudur?', 'Sürekli kopup yeniden kurulur; tek bir bağın ömrü çok kısadır.', ['Buzdaki gibi kalıcıdır ve sıvıda hiç kopmaz.', 'Sıvı suda hiç bulunmaz; yalnız buzda oluşur.', 'Kovalent bağlar kadar güçlü olduğundan sıvı akışkan olamaz.'], 'Sıvı suda moleküller sürekli hareket eder; hidrojen bağları pikosaniyeler ölçeğinde kopup başka komşularla yeniden kurulur. Bu dinamik ağ hem akışkanlığı hem de yüksek kaynama noktasını açıklar.'),
  ('Metanol (CH₃OH) 65 °C\'de, metantiyol (CH₃SH) ise yaklaşık 6 °C\'de kaynar. Metantiyolün molekül kütlesi daha büyük olduğuna göre bu farkın nedeni nedir?', 'S–H grubunun anlamlı hidrojen bağı kuramaması', ['Kükürdün oksijenden daha elektronegatif olması', 'Metantiyolün iyonik bir bileşik olması', 'Metanol moleküllerinin daha fazla elektron içermesi'], 'Oksijene bağlı H güçlü hidrojen bağı verir. Kükürt daha az elektronegatif ve daha büyüktür; S–H···S etkileşimi çok zayıftır. Bu yüzden ağır olmasına rağmen metantiyol daha uçucudur.'),
  ('Propilamin (CH₃CH₂CH₂NH₂) ile trimetilamin [(CH₃)₃N] aynı formüle (C₃H₉N) sahiptir; ancak propilamin çok daha yüksek sıcaklıkta kaynar. Nedeni nedir?', 'Trimetilaminde azota bağlı hidrojen bulunmaması', ['Trimetilaminde azotun ortaklanmamış çift taşımaması', 'Propilaminin iyonik bir katı olması', 'Trimetilaminin molekül kütlesinin çok daha büyük olması'], 'Propilaminin N–H grupları moleküller arası hidrojen bağı kurar. Trimetilaminde azot üç metile bağlıdır; çifti olsa da verici H yoktur ve kendi molekülleri arasında hidrojen bağı oluşmaz.'),
  ('Dimetil eter (CH₃OCH₃) kendi molekülleri arasında hidrojen bağı yapamadığı hâlde suda oldukça iyi çözünür. Bunun açıklaması hangisidir?', 'Eter oksijenindeki ortaklanmamış çiftlerin sudaki H atomlarıyla hidrojen bağı kurması', ['Eterin suyla tepkimeye girerek iki metanol oluşturması', 'Eterin suda iyonlarına ayrışması ve oluşan iyonların su molekülleriyle iyon-dipol etkileşimi kurması', 'Eterin apolar olup suyla London kuvvetleri kurması'], 'Eter yalnız hidrojen bağı alıcısıdır. Kendi moleküllerinde verici H olmadığı için aralarında bağ yoktur; ancak su verici H sağladığında eter oksijeni bu bağa katılır.'),
  ('Hidrojen bağının en güçlü olduğu düzen hangisidir?', 'Verici atom, hidrojen ve alıcı atomun aynı doğru üzerinde durduğu düzen', ['Hidrojenin verici ve alıcı atomlar arasında 90° açıyla, köşede durduğu bükük düzen', 'Verici ile alıcının aynı atom olduğu düzen', 'Hidrojenin alıcıdan olabildiğince uzak olduğu düzen'], 'Hidrojen bağı yönlüdür. X–H···Y açısı 180°\'ye yaklaştıkça hidrojenin kısmi artı yükü alıcının çiftine en etkili biçimde yönelir ve etkileşim güçlenir.'),
  ('Selüloz liflerinin çok sağlam olması ve suda çözünmemesi hangi etkileşimle ilgilidir?', 'Paralel zincirlerdeki –OH grupları arasındaki zincirler arası hidrojen bağları', ['Zincirler arasındaki iyonik bağlar', 'Zincirleri birbirine bağlayan disülfür köprüleri', 'Zincirlerin hücre içindeki metal iyonlarıyla kurduğu çok sayıda koordine kovalent bağ'], 'Selülozun düz zincirleri yan yana dizilir ve her zincirdeki –OH grupları komşu zincirlerle hidrojen bağı kurar. Bu sıkı ağ lifleri güçlendirir ve su moleküllerinin araya girmesini zorlaştırır.'),
  ('Cam kılcal borularda suyun yükselme yüksekliği için hangisi doğrudur?', 'Boru inceldikçe su daha yükseğe çıkar.', ['Boru kalınlaştıkça su daha yükseğe çıkar.', 'Borunun çapı yükselme yüksekliğini hiç etkilemez.', 'İnce borularda su seviyesi dışarıdakinin altına iner.'], 'Kılcal yükselme, su ile cam arasındaki yapışma kuvvetinin sütunu yukarı çekmesiyle olur. Dar boruda kaldırılması gereken su kütlesi çevreye göre küçük olduğundan sütun daha yükseğe çıkar; yükseklik boru yarıçapıyla ters orantılıdır.'),
  ('Naftalin topaklarının dolapta zamanla küçülüp kaybolmasından naftalin katısı hakkında hangi sonuç çıkarılabilir?', 'Moleküller arası çekimi zayıf, buhar basıncı belirgin bir moleküler katı olduğu', ['Güçlü iyonik bağlarla tutunan ve havadaki nemle yavaşça çözünen bir iyonik katı olduğu', 'Kovalent ağ yapısında, çok yüksek erime noktalı bir katı olduğu', 'Havadaki oksijenle hızla yanarak yok olduğu'], 'Naftalin molekülleri birbirine yalnız London kuvvetleriyle bağlıdır. Bu zayıf çekim oda sıcaklığında bile moleküllerin doğrudan gaz hâline geçmesine (süblimleşmeye) izin verir.'),
  ('[Fe(CN)₆]⁴⁻ kompleks iyonunda demirin koordinasyon sayısı ve yükseltgenme basamağı nedir?', '6 ve +2', ['6 ve +3', '4 ve +2', '6 ve +4'], 'Demire altı CN⁻ ligandı bağlıdır, koordinasyon sayısı 6\'dır. x + 6(−1) = −4 eşitliğinden demirin yükseltgenme basamağı +2 bulunur.'),
  ('Etilendiamin (H₂N–CH₂–CH₂–NH₂) ligandı bir metal iyonuna nasıl bağlanır?', 'İki azot atomuyla aynı anda bağlanan iki dişli bir ligand olarak', ['Yalnız bir karbon atomuyla bağlanan ve halka kuramayan tek dişli bir ligand olarak', 'Altı ayrı atomla bağlanan altı dişli bir ligand olarak', 'Metal iyonuyla iyonik bağ yapan bir karşı iyon olarak'], 'Her iki uçtaki azot birer ortaklanmamış çift taşır ve aynı metal iyonuna bağlanarak beş üyeli bir halka oluşturur. Bu tür halka kuran ligandlara şelat ligandı denir.'),
  ('Şelat etkisi olarak bilinen olgu hangisidir?', 'Çok dişli ligand komplekslerinin tek dişli eşdeğerlerinden daha kararlı olması', ['Tek dişli ligandların her zaman çok dişlilerden daha güçlü bağlanması', 'Metal iyonlarının ligand bağlandıkça yükünü tamamen kaybedip nötr atoma dönüşmesi', 'Ligandların metal iyonundan elektron alması'], 'Bir şelat ligandı birden çok noktadan bağlandığından, bir kez tutunduktan sonra tamamen ayrılması zordur; ayrıca daha az sayıda molekülle aynı bağlanma sağlandığı için entropi bakımından da avantajlıdır.'),
  ('Tiyosiyanat (SCN⁻) gibi bazı ligandların metal iyonuna iki farklı atomuyla bağlanabilmesine ne ad verilir?', 'Ambidentat (iki uçlu) ligand', ['Şelat oluşumu', 'Köprü kuran çok dişli ligand', 'Genişlemiş oktet'], 'SCN⁻ ligandı metale kükürt ya da azot ucundan bağlanabilir; bu iki bağlanma farklı bağlanma izomerleri verir. NO₂⁻ de N ya da O ucundan bağlanabilen bir örnektir.'),
  ('1916\'da yayımladığı \'Atom ve Molekül\' makalesinde kovalent bağı iki atomun bir elektron çiftini paylaşması olarak tanımlayan bilim insanı kimdir?', 'Gilbert N. Lewis', ['Walther Ludwig Kossel', 'Linus Pauling', 'Fritz London'], 'Lewis, 1916 tarihli makalesinde ortaklaşılan elektron çifti fikrini ortaya koydu. Aynı yıl Kossel iyonik bağı elektron aktarımıyla açıkladı.'),
  ('Ksenonun bileşiklerinin çoğunu flor ve oksijenle yapmasının nedeni nedir?', 'Bu elementlerin ksenonun elektronlarını çekecek kadar elektronegatif olması', ['Flor ve oksijenin soy gaz düzeninde olması', 'Ksenonun yalnız metallerle bağ yapabilmesi ve flor ile oksijeni metal gibi kullanması', 'Flor ve oksijen atomlarının ksenondan büyük olması'], 'Ksenonun dış elektronları büyük atom nedeniyle görece gevşek tutulur. Yalnız en elektronegatif elementler bu elektronları bağa çekecek kadar güçlüdür.'),
  ('Okyanus tabanında ve donmuş topraklarda bulunan metan hidrat (\'yanan buz\') yapısal olarak nedir?', 'Hidrojen bağlı su kafeslerinin içinde hapsolmuş metan molekülleri', ['Metanın suyla tepkimeye girip oluşturduğu iyonik tuz', 'Metan ile suyun kovalent bağlarla birbirine bağlandığı uzun zincirli bir polimer', 'Donmuş metan molekülleriyle karışmış saf buz kristalleri'], 'Metan hidrat bir klatrattır: su molekülleri hidrojen bağlarıyla çok yüzlü kafesler kurar, metan bu boşluklara kimyasal bağ kurmadan yerleşir. Tutuşturulunca açığa çıkan metan yanar.'),
  ('Bağ enerjileri H–H 436, O=O 498 ve O–H 463 kJ/mol ise 2H₂(g) + O₂(g) → 2H₂O(g) tepkimesinin ΔH değeri yaklaşık kaç kJ\'dir?', '−482', ['+482', '−1370', '−926'], 'Kırılan bağlar: 2 × 436 + 498 = 1370 kJ. Oluşan bağlar: 4 × 463 = 1852 kJ. ΔH = 1370 − 1852 = −482 kJ.'),
  ('H₂(g) + F₂(g) → 2HF(g) tepkimesinin ΔH değeri −540 kJ\'dir. H–H bağ enerjisi 436, F–F bağ enerjisi 158 kJ/mol olduğuna göre H–F bağ enerjisi yaklaşık kaç kJ/mol\'dür?', '567', ['1134', '297', '270'], 'ΔH = (436 + 158) − 2x = −540 eşitliğinden 2x = 1134, x = 567 kJ/mol bulunur. H–F bağı bilinen en güçlü tekli bağlardandır.'),
  ('Karbon monoksitteki C≡O bağı (yaklaşık 1072 kJ/mol) için hangisi doğrudur?', 'Nötr iki atomlu moleküller arasında bilinen en güçlü bağdır.', ['İyonik bir bağdır ve suda kolayca kopar.', 'N≡N bağından belirgin biçimde zayıftır; bu yüzden CO, N₂\'ye göre daha kolay ayrışır.', 'Tekli bir bağ olduğu için enerjisi düşüktür.'], 'CO\'daki üçlü bağın enerjisi N₂\'deki N≡N bağından (yaklaşık 945 kJ/mol) bile büyüktür. Bu değer bilinen en yüksek bağ ayrışma enerjisidir.'),
  ('Karbon uzun C–C zincirleri kurabildiği hâlde silisyumun uzun Si–Si zincirleri kararlı değildir. Bunun başlıca nedeni hangisidir?', 'Si–Si bağının C–C bağından belirgin biçimde zayıf olması', ['Silisyumun yalnız iki bağ yapabilmesi', 'Silisyumun elektronegatifliğinin karbondan çok büyük olup zinciri polarlaştırması', 'Si–Si bağlarının π bağı içermesi nedeniyle'], 'Silisyum atomu daha büyüktür ve orbitalleri daha zayıf örtüşür; Si–Si bağı (yaklaşık 226 kJ/mol) C–C bağından (yaklaşık 348 kJ/mol) çok daha zayıftır. Silisyum bunun yerine güçlü Si–O bağlarını tercih eder.'),
  ('Hidrojen peroksit ve diğer peroksitlerin kolayca bozunmasının yapısal nedeni hangisidir?', 'O–O tekli bağının oldukça zayıf olması', ['O–H bağlarının iyonik olması', 'Peroksitlerde oksijen atomlarının oktetinin eksik olması', 'Peroksit iyonunun üçlü bağ içermesi'], 'O–O tekli bağının enerjisi yalnız yaklaşık 146 kJ/mol\'dür. Komşu oksijenlerdeki ortaklanmamış çiftlerin itmesi bağı zayıflatır; bu bağ kolayca kopar ve peroksitler tepkimeye yatkın olur.'),
  ('Bağ enerjileri neden gaz hâlindeki maddeler için tanımlanır?', 'Moleküller arası etkileşimlerin hesaba karışmasını önlemek için', ['Gazlarda bağların hiç bulunmaması ve yalnız atomların serbestçe dolaşması nedeniyle', 'Katı ve sıvılarda bağların kırılamaması nedeniyle', 'Gaz moleküllerinin her zaman iyonik olması nedeniyle'], 'Sıvı ya da katı bir maddede bağ koparılırken moleküller arası çekimler de aşılır. Gaz hâlinde moleküller birbirinden bağımsız olduğundan ölçülen enerji yalnız o bağa aittir.'),
  ('O₂, O₃ ve H₂O₂ moleküllerindeki oksijen–oksijen bağ uzunlukları kısadan uzuna nasıl sıralanır?', 'O₂ < O₃ < H₂O₂', ['H₂O₂ < O₃ < O₂', 'O₃ < O₂ < H₂O₂', 'O₂ < H₂O₂ < O₃'], 'O₂\'de ikili bağ (derece 2), ozonda rezonans nedeniyle 1,5 dereceli bağlar, H₂O₂\'de tekli O–O bağı vardır. Bağ derecesi azaldıkça bağ uzar.'),
  ('C–F (yaklaşık 485 kJ/mol) ve C–I (yaklaşık 240 kJ/mol) bağ enerjileri dikkate alındığında hangi sonuç çıkarılabilir?', 'Organik iyot bileşiklerindeki C–I bağı çok daha kolay kopar.', ['C–F bağı C–I bağından daha uzundur.', 'Florlu organik bileşikler iyotlulardan çok daha kolay tepkimeye girer ve bozunur.', 'İki bağın kopması için gereken enerji eşittir.'], 'C–I bağı uzun ve zayıftır; ışıkla ya da ısıyla kolayca kopar. C–F bağı ise kısa ve güçlüdür; bu nedenle florlu bileşikler genellikle çok kararlıdır.'),
  ('Asetonitril (CH₃–C≡N) molekülünde metil karbonu, nitril karbonu ve azot atomunun hibritleşmeleri sırasıyla nedir?', 'sp³, sp, sp', ['sp³, sp², sp', 'sp², sp, sp³', 'sp, sp, sp²'], 'Metil karbonu dört tekli bağ yapar (sp³). Nitril karbonu bir tekli ve bir üçlü bağla iki elektron grubuna sahiptir (sp). Azot üçlü bağ ve bir ortaklanmamış çiftle iki gruba sahiptir (sp).'),
  ('Kükürt dioksit (SO₂) ve sülfat iyonundaki (SO₄²⁻) kükürt atomlarının hibritleşmeleri sırasıyla hangisidir?', 'sp² ve sp³', ['sp³ ve sp²', 'sp ve sp³', 'sp² ve sp³d²'], 'SO₂\'de kükürt iki bağ grubu ve bir ortaklanmamış çift olmak üzere üç elektron grubuna sahiptir (sp²). Sülfatta dört oksijene bağlı kükürt dört grup taşır (sp³).'),
  ('BF₃ molekülü bir F⁻ iyonuyla birleşip BF₄⁻ iyonuna dönüştüğünde borun hibritleşmesi ve geometrisi nasıl değişir?', 'sp²\'den sp³\'e; üçgen düzlemden dörtyüzlüye', ['sp³\'ten sp²\'ye; dörtyüzlüden üçgen düzleme', 'sp\'den sp²\'ye; doğrusaldan üçgen düzleme', 'Değişmez; ikisi de sp² hibritleşmiş ve üçgen düzlemdir.'], 'Borun boş p orbitali F⁻\'nin elektron çiftini kabul eder. Dört elektron grubu oluşunca bor sp³ hibritleşir ve iyon dörtyüzlü olur.'),
  ('Katı fosfor pentaklorür, ayrık PCl₅ molekülleri yerine [PCl₄]⁺ ve [PCl₆]⁻ iyonlarından oluşur. Bu iyonların geometrileri nedir?', '[PCl₄]⁺ dörtyüzlü, [PCl₆]⁻ sekizyüzlü', ['[PCl₄]⁺ kare düzlem, [PCl₆]⁻ üçgen çift piramit', 'İkisi de üçgen çift piramit', '[PCl₄]⁺ üçgen piramit, [PCl₆]⁻ kare piramit'], '[PCl₄]⁺ iyonunda fosfor dört bağ grubuna, [PCl₆]⁻ iyonunda altı bağ grubuna sahiptir ve ikisinde de ortaklanmamış çift yoktur. VSEPR dörtyüzlü ve sekizyüzlü düzenleri öngörür.'),
  ('Kırık doğru (açısal) şekilli üç atomlu bir molekülün merkez atomu çevresinde kaç elektron grubu bulunabilir?', '3 ya da 4', ['Yalnız 2', 'Yalnız 5', '5 ya da 6, ama asla 3'], 'Açısal şekil, üç elektron grubunun biri ortaklanmamış çift olduğunda (SO₂) ya da dört grubun ikisi ortaklanmamış çift olduğunda (H₂O) ortaya çıkar. İki grup doğrusal şekil verir.'),
  ('Merkez atomu üç atoma bağlı olan bir molekülün mutlaka düzlemsel olduğunu söyleyen bir öğrenciye hangi örnek karşı kanıt oluşturur?', 'PCl₃', ['BCl₃', 'SO₃', 'AlCl₃'], 'PCl₃\'te fosfor bir ortaklanmamış çift taşır; molekül üçgen piramittir. BCl₃, SO₃ ve gaz hâlindeki AlCl₃ monomeri ise üçgen düzlemdir.'),
  ('Teflon kaplı tavalara yiyeceklerin yapışmamasının moleküller arası etkileşimler açısından açıklaması hangisidir?', 'Florlu yüzeyin zor kutuplanıp ancak zayıf London çekimi kurması', ['Teflonun yiyeceklerle iyonik bağ kurup onları itmesi', 'Teflon yüzeyinin sürekli su buharı üretmesi', 'Teflonun ısıtılınca erimesi ve yiyeceğin bu sıvı tabakanın üzerinde kayarak ilerlemesi'], 'Teflonun yüzeyi sıkıca tutulan elektronlara sahip flor atomlarıyla kaplıdır. Bu yüzey kalıcı dipol taşımaz ve zor kutuplanır; temas eden maddelerle çok zayıf çekim kurar.'),
  ('Molibden disülfürün (MoS₂) grafit gibi kuru kayganlaştırıcı olarak kullanılabilmesinin yapısal nedeni hangisidir?', 'Katmanlar arasında yalnız zayıf van der Waals kuvvetleri bulunması', ['Kristalinde serbest Mo atomlarının bulunması', 'Molekülleri arasında güçlü hidrojen bağları bulunması ve bunların sürekli kopup yeniden oluşması', 'Oda sıcaklığında sıvı olması'], 'MoS₂ katmanlı bir yapıya sahiptir. Katmanlar arasındaki zayıf çekim, kuvvet uygulandığında katmanların birbiri üzerinde kolayca kaymasına izin verir.'),
  ('Islak saç bir biçim verilerek kurutulduğunda o biçimi bir süre korur; saç yeniden ıslanınca biçim kaybolur. Bu davranış en çok hangi etkileşimle ilgilidir?', 'Keratin zincirleri arasındaki hidrojen bağlarının ıslanınca bozulup kururken yeniden kurulması', ['Saçtaki peptit bağlarının suyla hidroliz olup kururken yeniden kurulması', 'Keratindeki disülfür köprülerinin suyla kalıcı olarak kopması ve kururken asla yeniden oluşmaması', 'Saç tellerinin suyla iyonik bağ kurup sertleşmesi'], 'Su molekülleri saçtaki zincirler arası hidrojen bağlarının yerine geçer. Saç şekil verilmiş hâlde kuruyunca hidrojen bağları yeni konumlarda yeniden oluşur. Kalıcı şekil için ise disülfür köprülerini değiştiren kimyasal işlem gerekir.'),
  ('Diboran (B₂H₆) molekülünde iki bor atomunu birbirine bağlayan köprü hidrojenlerinin bağlanma türü hangisidir?', 'Üç merkezli iki elektronlu bağ', ['Normal iki merkezli iki elektronlu bağ', 'İyonik bağ', 'Hidrojen bağı'], 'Borun değerlik elektronu azdır. Köprüdeki her B–H–B birimi, üç atomu yalnız bir elektron çiftiyle bir arada tutar; bu elektron eksikliğine çözüm olarak oluşan özel bir bağ türüdür.'),
  ('AlCl₃ bir Cl⁻ iyonuyla birleşerek AlCl₄⁻ iyonunu oluşturduğunda yeni bağ için hangisi doğrudur?', 'Cl⁻ çifti verir, alüminyum alır; bağ koordine kovalenttir.', ['Alüminyum elektron çifti verir, Cl⁻ alır; bağ iyoniktir.', 'Her iki atom birer elektron verir; oluşan bağ apolar kovalent bir bağdır.', 'Bağ hidrojen bağıdır; çünkü klor elektronegatiftir.'], 'AlCl₃\'teki alüminyumun oktet eksiği vardır ve bir Lewis asidi gibi davranır. Cl⁻ iyonu ortaklanmamış çiftini vererek koordine kovalent bağ kurar; oluşan AlCl₄⁻ dörtyüzlüdür.'),
  ('Nikel tetrakarbonil [Ni(CO)₄] bileşiğinde CO ligandları nikel atomuna hangi atomları üzerinden bağlanır?', 'Karbon atomları', ['Oksijen atomları', 'Hem karbon hem oksijen atomları', 'Bağ kurmaz, yalnız çevreler'], 'CO\'da eksi formal yük ve en yüksek enerjili ortaklanmamış çift karbondadır. Bu yüzden karbonil ligandları metale karbon ucundan bağlanır.'),
  ('Şeker suda çözündüğünde aşağıdakilerden hangisi gerçekleşmez?', 'Sakkaroz moleküllerindeki kovalent bağların kopması', ['Şeker molekülleri arasındaki hidrojen bağlarının bozulması', 'Şeker ile su arasında yeni hidrojen bağları kurulması', 'Su molekülleri arasındaki bazı hidrojen bağlarının bozulması'], 'Çözünme fiziksel bir olaydır. Şeker molekülleri bozulmadan su moleküllerinin arasına dağılır; yalnız moleküller arası etkileşimler değişir.'),
  ('Sodyum peroksit (Na₂O₂) katısında aşağıdaki bağlardan hangisi bulunur?', 'O–O arasında apolar kovalent bağ', ['Na–Na arasında metalik bağ', 'Na–O arasında koordine kovalent bağ', 'O–O arasında iyonik bağ'], 'Na₂O₂, iki Na⁺ ve bir peroksit iyonundan (O₂²⁻) oluşur. Peroksit iyonundaki iki oksijen aynı element olduğundan aralarındaki tekli bağ apolar kovalenttir; iyonlar arasında ise iyonik bağ vardır.'),
  ('Metallerin elektrik iletkenliğinin sıcaklık arttıkça azalmasının nedeni nedir?', 'Daha şiddetli titreşen katyonların elektronları daha çok saçması', ['Isıtılınca serbest elektron sayısının hızla azalması', 'Metalin ısıyla iyonik bir katıya dönüşmesi', 'Yüksek sıcaklıkta elektron denizinin tamamen buharlaşması'], 'Isıtılan metalde katyonların örgü titreşimleri büyür. Hareket eden elektronlar bu titreşen iyonlara daha sık çarpar; direnç artar, iletkenlik azalır.'),
  ('A maddesi 1083 °C\'de eriyor ve katıyken iletken; B maddesi 801 °C\'de eriyor, katıyken yalıtkan ama eriyiği iletken; C maddesi 114 °C\'de eriyor ve hiçbir hâlde iletmiyor. Bu maddeler sırasıyla hangi katı türündedir?', 'Metalik, iyonik, moleküler', ['İyonik, metalik, moleküler', 'Metalik, kovalent ağ, iyonik', 'Moleküler, iyonik, metalik'], 'Katı hâlde iletkenlik metalik bağın, yalnız eriyikte iletkenlik iyonik bağın göstergesidir. Düşük erime noktası ve iletkenlik olmaması moleküler katıyı (örneğin iyot) gösterir.'),
  ('Aşağıdaki katılardan hangisinin erimesi sırasında yalnız moleküller arası etkileşimler aşılır?', 'Sakkaroz', ['Magnezyum oksit', 'Kuvars', 'Demir'], 'Şeker moleküler bir katıdır; eridiğinde moleküller bozulmaz, yalnız aralarındaki hidrojen bağları ve diğer zayıf etkileşimler aşılır. MgO\'da iyonik, kuvarsta kovalent, demirde metalik bağlar bozulur.'),
  ('Potasyum nitrat (KNO₃) suda çözündüğünde hangi bağlar bozulur, hangileri korunur?', 'K⁺–NO₃⁻ iyonik bağları bozulur; nitrat içindeki kovalent bağlar korunur.', ['Nitrat içindeki N–O kovalent bağları kopar; K⁺ ile NO₃⁻ bağlı kalır.', 'Hiçbir bağ bozulmaz; katı yalnızca gözle görülemeyecek kadar küçük kristal parçalarına ayrılır.', 'Bütün bağlar bozulur ve K, N ve O atomları serbest kalır.'], 'Çözünmede örgüdeki iyonlar su molekülleriyle sarılarak birbirinden ayrılır. Çok atomlu nitrat iyonu bir bütün olarak çözeltiye geçer; içindeki kovalent bağlar kopmaz.'),
  ('Amonyak (NH₃) ile hidrojen klorür (HCl) gazlarının tepkimesiyle oluşan katı ürünü bir arada tutan bağlar için hangisi doğrudur?', 'Ürün iyoniktir; NH₄⁺ içinde kovalent bağlar vardır.', ['Ürün moleküler bir katıdır; yalnız hidrojen bağları içerir.', 'Ürün metalik bir katıdır; elektron denizi içerir.', 'Ürün kovalent ağ katısıdır; bütün atomlar tek bir ağda bağlıdır.'], 'NH₃, HCl\'den bir proton alarak NH₄⁺ oluşturur; geriye Cl⁻ kalır. Bu iyonlar NH₄Cl kristalinde iyonik bağla tutunur, NH₄⁺ içinde ise N–H kovalent bağları bulunur.'),
  ('Bir elementin oksidi suda çözünmüyor, 1700 °C\'nin üzerinde eriyor, çok sert ve hiçbir hâlde elektrik iletmiyor. Bu oksit için en olası örnek hangisidir?', 'SiO₂', ['Na₂O', 'CO₂', 'SO₂'], 'Bu özellikler kovalent ağ katısını gösterir. SiO₂ böyle bir yapıdadır. Na₂O iyonik olduğundan eriyiği iletir; CO₂ ve SO₂ ise oda sıcaklığında gazdır.'),
  ('Hidrojen klorür gaz hâlinde moleküler olduğu hâlde suda çözündüğünde çözelti elektriği iletir. Bunun nedeni nedir?', 'Polar HCl\'nin suyla tepkimeye girip iyonlar oluşturması', ['HCl molekülünün aslında iyonik bir katı olması ve gazda da iyon taşıması', 'Suyun tek başına çok iyi bir iletken olması', 'Klor atomlarının suda metalik bağ kurması'], 'HCl molekülü suya bir proton aktarır ve H₃O⁺ ile Cl⁻ iyonları oluşur. Hareketli iyonlar çözeltiyi iletken yapar; saf HCl gazı ise iyon içermez.'),
  ('Kalsiyum karbür (CaC₂) iyonik bir bileşiktir. Karbür iyonunda (C₂²⁻) iki karbon arasındaki bağ hangisidir?', 'Üçlü bağ', ['Tekli bağ', 'İkili bağ', 'İyonik bağ'], 'C₂²⁻ iyonunda 4 + 4 + 2 = 10 değerlik elektronu vardır ve iyon N₂ ile izoelektroniktir. Her iki karbonun oktete ulaşması için aralarında üçlü bağ ve her birinde bir ortaklanmamış çift bulunur.'),
  ('Aşağıdaki maddelerden hangisi yalnız apolar kovalent bağlar içeren apolar bir moleküldür?', 'P₄', ['HCl', 'NH₃', 'CO₂'], 'Beyaz fosfordaki P₄ molekülünde bütün bağlar aynı atomlar arasındadır ve molekül simetriktir. CO₂ apolar olsa da polar C=O bağları içerir; HCl ve NH₃ polar moleküllerdir.'),
  ('Bir kovalent bağın homolitik (simetrik) bölünmesinde elektronlar nasıl paylaşılır?', 'Her atom bağ elektronlarından birini alır ve iki radikal oluşur.', ['İki elektronun ikisi de elektronegatif atoma gider ve iyonlar oluşur.', 'Elektronlar bağda kalır, yalnız çekirdekler birbirinden uzaklaşır.', 'Elektronların ikisi de daha az elektronegatif atoma gider ve iki nötr molekül oluşur.'], 'Homolitik bölünmede bağ elektron çifti eşit olarak ayrılır; her parça eşleşmemiş bir elektron taşıyan radikal olur. Işıkla Cl₂\'nin iki Cl atomuna ayrılması buna örnektir.'),
  ('Proteinlerin β-kırmalı tabaka yapısında hidrojen bağları nerede kurulur?', 'Yan yana uzanan zincir parçalarının C=O ve N–H grupları arasında', ['Yalnız aynı zincirdeki ardışık iki amino asidin yan zincirleri arasında, zincir boyunca', 'Yan zincirlerdeki metal iyonları ile su arasında', 'Sistein yan zincirlerinin kükürt atomları arasında'], 'β-tabakada uzamış zincir parçaları yan yana dizilir. Bir parçanın C=O grupları komşu parçanın N–H gruplarıyla hidrojen bağı kurarak kırmalı bir yüzey oluşturur.'),
  ('Değerlik bağı kuramı ile molekül orbital kuramı arasındaki temel fark hangisidir?', 'DB kuramında elektronlar iki atom arasında yerelleşir; MO kuramında moleküle yayılır.', ['DB kuramı yalnız iyonik, MO kuramı yalnız metalik bağları açıklar.', 'İki kuram da elektronları yalnız tek bir atoma yerleştirir.', 'MO kuramı bağ açılarını hesaplamak için hibrit orbitaller kullanır, DB kuramı ise hibritleşmeyi hiç kullanmaz.'], 'Değerlik bağı kuramı bağı, iki atom orbitalinin örtüşmesiyle kurulan yerel bir çift olarak görür. Molekül orbital kuramı ise atom orbitallerini birleştirip molekülün tamamına ait yeni orbitaller kurar.'),
  ('Halojen bağı olarak adlandırılan etkileşim hangisidir?', 'Halojen atomunun kısmi artı bölgesi ile bir Lewis bazı arasındaki çekim', ['İki halojen atomu arasındaki tekli kovalent bağ', 'Halojenür iyonu ile metal katyonu arasındaki iyonik bağ', 'Halojene bağlı hidrojenin komşu moleküldeki ortaklanmamış çiftle kurduğu hidrojen bağı'], 'C–I ya da C–Br bağındaki halojenin bağ ekseni uzantısında kısmi artı bir bölge oluşur. Bu bölge bir ortaklanmamış çifti çekerek hidrojen bağına benzer, yönlü bir etkileşim kurar.'),
  ('Suyun dielektrik sabitinin yüksek (yaklaşık 80) olması, iyonik maddelerin suda çözünmesi açısından hangi sonucu doğurur?', 'İyonlar arasındaki çekimi büyük ölçüde zayıflatması', ['Suyun elektriği metaller kadar iyi iletmesini sağlaması', 'Su moleküllerinin iyonlaşıp iyonlarla metalik bağ kurması', 'Suyun apolar maddeleri de iyonlarına ayırabilmesi'], 'Su molekülleri iyonların çevresinde yönlenerek onların elektrik alanını perdeler. Böylece zıt yüklü iyonlar arasındaki çekim vakumdakine göre yaklaşık 80 kat azalır ve iyonik katılar çözünebilir.'),
  ('Metanol (CH₃OH), florometan (CH₃F) ve etan (C₂H₆) molekül kütleleri birbirine yakındır. Kaynama noktalarının büyükten küçüğe sıralaması hangisidir?', 'CH₃OH > CH₃F > C₂H₆', ['C₂H₆ > CH₃F > CH₃OH', 'CH₃F > CH₃OH > C₂H₆', 'CH₃OH > C₂H₆ > CH₃F'], 'Metanol hidrojen bağı yapar. Florometan polardır ve dipol-dipol etkileşimi gösterir; ancak flor karbona bağlı olduğundan hidrojen bağı yoktur. Apolar etanda yalnız London kuvvetleri vardır.'),
  ('Molekül kütleleri yakın olan F₂ (38 g/mol) ile HCl (36,5 g/mol) karşılaştırıldığında hangisi doğrudur?', 'HCl dipol-dipol etkileşimi nedeniyle daha yüksek sıcaklıkta kaynar.', ['F₂ daha elektronegatif olduğu için daha yüksek sıcaklıkta kaynar.', 'İkisi tam olarak aynı sıcaklıkta kaynar.', 'HCl molekülleri arasında güçlü hidrojen bağı vardır; F₂\'de London kuvveti bile yoktur.'], 'Benzer kütlede ve elektron sayısında London kuvvetleri yakındır. HCl\'nin kalıcı dipolü ek çekim sağlar; bu yüzden HCl (−85 °C) F₂\'den (−188 °C) çok daha yüksek sıcaklıkta kaynar.'),
  ('Br₂ (160 g/mol) 59 °C\'de, ICl (162 g/mol) ise yaklaşık 97 °C\'de kaynar. Bu farkı en iyi açıklayan hangisidir?', 'ICl\'nin polar olup ek olarak dipol-dipol etkileşimi göstermesi', ['ICl\'nin daha az elektron içermesi ve bu yüzden daha sıkı tutunması', 'Br₂ molekülleri arasında hidrojen bağı bulunması', 'ICl\'nin iyonik bir bileşik olup I⁺ ve Cl⁻ iyonlarından oluşması'], 'Kütleleri ve London kuvvetleri benzer iki molekülden ICl farklı elektronegatiflikte atomlar içerdiği için kalıcı bir dipole sahiptir. Bu ek çekim kaynama noktasını yükseltir.'),
  ('Propan (44 g/mol), asetaldehit (CH₃CHO, 44 g/mol) ve etanol (46 g/mol) için kaynama noktası sıralaması hangisidir?', 'Etanol > asetaldehit > propan', ['Propan > asetaldehit > etanol', 'Asetaldehit > etanol > propan', 'Etanol > propan > asetaldehit'], 'Propan apolardır (−42 °C). Asetaldehit polardır ancak kendi molekülleri arasında hidrojen bağı yoktur (20 °C). Etanol –OH grubuyla hidrojen bağı kurar (78 °C).'),
  ('Etilen glikol (HOCH₂CH₂OH) 197 °C\'de, etanol 78 °C\'de kaynar. Molekül kütleleri arasındaki farktan çok daha büyük olan bu kaynama farkının başlıca nedeni nedir?', 'Etilen glikolün iki –OH grubuyla daha çok hidrojen bağı kurması', ['Etilen glikolün iyonik bir bileşik olması', 'Etanolün apolar bir molekül olup yalnız London kuvvetleriyle tutunması ve uçucu olması', 'Etilen glikolün kovalent ağ yapısında bulunması'], 'Her molekülde iki hidrojen bağı vericisi ve alıcı grup bulunduğundan moleküller arası ağ çok daha sıkıdır. Etilen glikolün antifriz olarak düşük uçuculuğu da buna dayanır.'),
  ('Bir öğrenci \'Molekül kütlesi büyük olan maddenin kaynama noktası her zaman daha yüksektir\' diyor. Bu genellemeyi çürüten örnek hangisidir?', 'Su (18 g/mol) ile H₂S (34 g/mol)', ['Cl₂ (71 g/mol) ile Br₂ (160 g/mol)', 'CH₄ (16 g/mol) ile C₂H₆ (30 g/mol)', 'He (4 g/mol) ile Ne (20 g/mol)'], 'Hafif su molekülleri hidrojen bağı yaptığından ağır H₂S\'den çok daha yüksek sıcaklıkta kaynar. Diğer çiftlerde etkileşim türü aynıdır ve kütle arttıkça kaynama noktası gerçekten yükselir.'),
  ('Magnezyum klorür (MgCl₂) 714 °C\'de, silisyum tetraklorür (SiCl₄) ise −69 °C\'de erir. Bu büyük farkın nedeni hangisidir?', 'MgCl₂\'nin iyonik örgü, SiCl₄\'ün ayrık moleküller oluşturması', ['SiCl₄\'ün MgCl₂\'den çok daha ağır olması ve moleküllerinin hızla hareket etmesi', 'MgCl₂ molekülleri arasında hidrojen bağı bulunması', 'SiCl₄\'ün metalik bağlı bir katı olması nedeniyle'], 'Metal ile ametal arasındaki büyük elektronegatiflik farkı MgCl₂\'yi iyonik yapar. Silisyum ile klor arasındaki fark küçüktür; SiCl₄ kovalent bağlı, apolar moleküllerden oluşur ve erimesi için yalnız zayıf London kuvvetleri aşılır.'),
  ('Mg²⁺ ve Na⁺ iyonlarının su molekülleriyle etkileşimi karşılaştırıldığında hangisi doğrudur?', 'Mg²⁺ daha küçük ve iki kat yüklü olduğundan suyu daha güçlü çeker.', ['Na⁺ daha büyük olduğu için suyu daha güçlü çeker.', 'İki iyonun hidratasyon enerjisi aynıdır.', 'Mg²⁺ su ile neredeyse hiç etkileşmez, çünkü soy gaz düzenindedir ve kararlıdır.'], 'İyon-dipol çekimi iyon yükü arttıkça ve iyon küçüldükçe güçlenir. Mg²⁺ hem daha yüklü hem daha küçük olduğundan hidratasyon enerjisi Na⁺\'ınkinin birkaç katıdır.'),
  ('Coulomb yasasına göre bir katyon ile bir anyon arasındaki uzaklık iki katına çıkarılırsa aralarındaki elektrostatik çekim kuvveti nasıl değişir?', 'Dörtte birine iner.', ['Yarısına iner.', 'İki katına çıkar.', 'Değişmeden aynı kalır.'], 'Coulomb kuvveti F = k·q₁·q₂ / r² bağıntısına uyar. r iki katına çıkınca r² dört katına çıkar ve kuvvet dörtte birine düşer. Bu yüzden büyük iyonlar arasındaki çekim zayıftır.'),
  ('Sülfüril klorür (SO₂Cl₂) molekülünde kükürt iki oksijen ve iki klora bağlıdır ve ortaklanmamış çifti yoktur. Kükürt çevresindeki geometri hangisidir?', 'Dörtyüzlü', ['Kare düzlem', 'Tahterevalli', 'Üçgen piramit'], 'Dört bağ grubu bulunan ve ortaklanmamış çift taşımayan kükürt, VSEPR\'e göre dörtyüzlü düzen kurar; bağlı atomlar farklı olduğu için açılar biraz bozulur.'),
  ('Aynı formül birimine sahip iyonik bileşiklerde aşağıdaki değişikliklerden hangisi örgü enerjisini en çok artırır?', 'İki iyonun da yükünü iki katına çıkarmak', ['Katyonun yarıçapını iki katına çıkarmak', 'Anyonun yarıçapını iki katına çıkarmak', 'Katı örneğin kütlesini iki katına çıkarmak'], 'Örgü enerjisi yük çarpımıyla doğru orantılıdır; iki yük de iki katına çıkarsa çekim yaklaşık dört katına çıkar. İyonları büyütmek uzaklığı artırıp çekimi azaltır; örnek kütlesi ise mol başına değeri etkilemez.'),
  ('Bir maddenin elektronegatiflik farkı 0 olan bağlardan oluşmasına karşın elektriği iyi iletmesi hangi bağ türüne işaret eder?', 'Metalik bağ', ['Apolar kovalent bağ', 'İyonik bağ', 'Hidrojen bağı'], 'Aynı tür atomlardan oluşan bir katı ya kovalent (elmas, kükürt) ya da metalik olabilir. Elektrik iletkenliği delokalize elektronların göstergesidir; bu da metalik bağı işaret eder.'),
  ('DNA\'da adeninin yalnız timinle, guaninin yalnız sitozinle eşleşmesinin bağ açısından nedeni hangisidir?', 'Verici ve alıcı grupların yalnız bu çiftlerde birbirine tam uyması', ['Bu bazlar arasında kovalent bağ kurulması', 'Adenin ile timinin aynı molekül kütlesine sahip olması', 'Bazların zıt yüklü iyonlar olup birbirini elektrostatik olarak çekmesi ve kilitlenmesi'], 'Her bazın kenarında belirli konumlarda H verici ve alıcı gruplar bulunur. A–T ve G–C çiftlerinde bu gruplar karşılıklı gelerek iki ve üç hidrojen bağı kurar; diğer eşleşmelerde gruplar uyuşmaz.'),
  ('Bir enzimin substratını tanıyıp aktif bölgesine bağlamasında genellikle hangi etkileşimler rol oynar?', 'Hidrojen bağı, iyonik ve van der Waals gibi çok sayıda zayıf etkileşim', ['Yalnız kalıcı kovalent bağlar', 'Yalnız metalik bağlar', 'Substrat ile enzim çekirdekleri arasındaki güçlü nükleer kuvvetler ve kütle çekimi'], 'Substratın bağlanması çoğunlukla kovalent olmayan zayıf etkileşimlerle olur. Bu etkileşimler hem seçici tanımayı sağlar hem de ürünün kolayca ayrılmasına izin verir.'),
  ('Aşağıdaki maddelerden hangisi suyla etkileşirken yalnız hidrojen bağı ALICISI olarak davranabilir?', 'Aseton', ['Metanol', 'Amonyak', 'Hidrojen florür'], 'Asetonda oksijene ya da azota bağlı H yoktur; yalnız karbonil oksijenindeki çiftler suyun hidrojenini kabul eder. Metanol, amonyak ve HF ise hem verici hem alıcı olabilir.'),
  ('Antikorların belirli bir antijeni seçici olarak tanıyabilmesi kimyasal açıdan hangi ilkeye dayanır?', 'Bağlanma bölgesinin antijenle şekil ve zayıf etkileşimler bakımından uyumu', ['Antikorun her antijenle her zaman kalıcı kovalent bağlar kurarak onu tutması', 'Antikorun antijeni metalik bağla sarması', 'Antijenin kütlesinin antikorunkine eşit olması'], 'Antikorun bağlanma bölgesi, antijenin yüzeyiyle hem biçim hem de hidrojen bağı, iyonik ve hidrofobik etkileşim noktaları bakımından tamamlayıcıdır. Çok sayıda zayıf etkileşimin birlikte oluşması güçlü ve seçici bağlanma sağlar.'),
  ('C₂, B₂, O₂ ve O₂⁺ moleküllerinden hangisi diamanyetiktir?', 'C₂', ['B₂', 'O₂', 'O₂⁺'], 'C₂\'de sekiz değerlik elektronu bağ yapan orbitallere eşleşmiş olarak yerleşir. B₂ ve O₂\'de iki, O₂⁺\'da bir eşleşmemiş elektron bulunur.'),
  ('Azot monoksit (NO) molekülünün molekül orbital kuramına göre bağ derecesi kaçtır?', '2,5', ['2', '3', '1,5'], 'NO\'da 11 değerlik elektronu vardır: sekizi bağ yapan, üçü karşıt bağ orbitallerinde bulunur (π*\'da bir elektron). Bağ derecesi (8 − 3)/2 = 2,5\'tir.'),
  ('HF molekülünde flor atomunun 2p orbitallerinden ikisi hidrojenin orbitaliyle hiç etkileşmez. Bu orbitaller MO kuramında nasıl adlandırılır?', 'Bağ yapmayan orbitaller', ['Karşıt bağ orbitalleri', 'Hibrit orbitaller', 'π bağ yapan orbitaller'], 'Hidrojenin 1s orbitali yalnız bağ eksenindeki 2p orbitaliyle örtüşebilir; eksene dik iki 2p orbitali simetri nedeniyle etkileşmez. Bu orbitallerdeki elektronlar Lewis yapısındaki ortaklanmamış çiftlere karşılık gelir.'),
  ('Bir molekül uygun dalga boyunda ışık soğurup bir elektronunu bağ yapan orbitalden karşıt bağ orbitaline çıkarırsa bağa ne olur?', 'Bağ derecesi düşer; bağ zayıflar ya da kopar.', ['Bağ derecesi artar ve bağ kısalır.', 'Bağ hiç etkilenmez, yalnız renk değişir.', 'Molekül hemen iyonik bir bileşiğe dönüşür.'], 'Elektronun bir bağ yapan orbitalden ayrılıp karşıt bağ orbitaline girmesi bağ derecesini bir azaltır. H₂ gibi tek bağlı moleküllerde bu durum bağın kopmasına yol açar; ışıkla bağ koparma buna dayanır.'),
  ('Elmasın yoğunluğu (yaklaşık 3,5 g/cm³) grafitinkinden (yaklaşık 2,2 g/cm³) büyüktür. Bu bilgiye göre grafitten yapay elmas üretmek için hangi koşul gereklidir?', 'Çok yüksek basınç', ['Çok düşük basınç', 'Oda koşullarında uzun süre bekletme', 'Grafiti suda çözüp yeniden kristallendirme'], 'Daha yoğun olan elmas aynı kütle için daha az hacim kaplar; yüksek basınç dönüşümü bu yöne iter. Endüstride yapay elmas binlerce atmosfer basınç ve yüksek sıcaklıkta üretilir.'),
  ('Nitrik asidin (HNO₃) en uygun Lewis yapısında azot atomunun formal yükü kaçtır?', '+1', ['0', '−1', '+5'], 'Azot bir O–H oksijenine tekli, bir oksijene ikili, bir oksijene tekli bağla bağlıdır; ortaklanmamış çifti yoktur. Formal yük 5 − 0 − 4 = +1\'dir; tekli bağlı uç oksijen −1 taşır.'),
  ('Cıvanın yüzey geriliminin sudan yaklaşık altı kat büyük olması neyle açıklanır?', 'Cıva atomları arasındaki metalik bağın hidrojen bağından güçlü olması', ['Cıva atomları arasında hidrojen bağı bulunması', 'Cıvanın apolar moleküllerden oluşup yalnız London kuvvetleriyle ve çok sıkı tutunması', 'Cıvanın yüzeyinde ince bir oksit tabakası oluşması'], 'Sıvı cıvadaki atomlar elektron denizi aracılığıyla birbirine bağlıdır. Bu çekim sudaki hidrojen bağlarından da güçlü olduğundan cıva damlaları yüzeylere yayılmaz, küçük küreler hâlinde kalır.'),
  ('Kobalt(II) klorür çözeltisine derişik HCl eklenince pembe renk maviye döner. Mavi renk hangi kompleks iyondan kaynaklanır?', 'Dörtyüzlü [CoCl₄]²⁻', ['Sekizyüzlü [Co(H₂O)₆]²⁺', 'Doğrusal [CoCl₂]', 'Kare düzlem [Co(H₂O)₄]²⁺'], 'Pembe renk sekizyüzlü [Co(H₂O)₆]²⁺ iyonuna aittir. Klorür derişimi artınca su ligandlarının yerini klorürler alır ve dörtyüzlü, mavi [CoCl₄]²⁻ oluşur.'),
  ('Ozonun oksijen gazından (O₂) çok daha tepkimeye yatkın olmasının bağ açısından bir nedeni hangisidir?', 'Ozondaki O–O bağlarının O₂\'dekinden düşük dereceli ve zayıf olması', ['Ozonun bir soy gaz olması', 'Ozon molekülünde hiç π bağı bulunmaması', 'O₂\'nin iyonik, ozonun ise kovalent bir molekül olması ve iyonların daha kararlı olması'], 'Ozondaki bağlar O₂\'deki ikili bağdan zayıftır; ozon kolayca bir oksijen atomu vererek O₂\'ye dönüşür. Bu da ozonu güçlü bir yükseltgen yapar.'),
  ('Stratosfere ulaşan CFC moleküllerinden morötesi ışıkla klor atomlarının ayrılması, flor atomlarının ise ayrılmaması neyle açıklanır?', 'C–Cl bağının C–F bağından daha zayıf olması', ['Flor atomlarının klor atomlarından daha ağır olması', 'C–F bağının iyonik, C–Cl bağının kovalent olması', 'Morötesi ışığın yalnız klor atomlarını görebilmesi'], 'C–Cl bağ enerjisi (yaklaşık 330 kJ/mol) C–F bağınınkinden (yaklaşık 485 kJ/mol) çok düşüktür. Morötesi fotonlar daha zayıf olan C–Cl bağını koparır ve ozonu yıkan klor atomları açığa çıkar.'),
  ('NaCl kristalinde birim hücrenin kenar uzunluğu 564 pm\'dir ve kenar boyunca iyonlar Na⁺–Cl⁻–Na⁺ biçiminde sıralanır. Buna göre en yakın Na⁺ ile Cl⁻ iyonlarının merkezleri arasındaki uzaklık kaç pm\'dir?', '282', ['564', '141', '399'], 'Kenar uzunluğu bir Na⁺ ile bir sonraki Na⁺ arasındaki uzaklıktır ve iki Na–Cl uzaklığına eşittir: 564 / 2 = 282 pm. Bu değer yaklaşık olarak iki iyonun yarıçapları toplamıdır.'),
  ('Grafitte bir katman içindeki C–C uzaklığı yaklaşık 142 pm, katmanlar arası uzaklık ise yaklaşık 335 pm\'dir. Bu verilerden hangi sonuç çıkar?', 'Katman içi bağlar kovalent; katmanlar arası yalnız zayıf etkileşim vardır.', ['Katmanlar birbirine kovalent bağlarla çok sıkı bağlıdır.', 'Katman içindeki bağlar iyoniktir.', 'Grafitteki bütün karbon atomları birbirinden eşit uzaklıkta durur ve aynı bağı kurar.'], '142 pm tipik bir kovalent bağ uzunluğudur (tekli ile ikili arasında). 335 pm ise kovalent bağ için çok uzundur ve van der Waals temas uzaklığına karşılık gelir; katmanların kolay kaymasının nedeni budur.'),
  ('Pencere camının görünür ışığı geçirmesi bant kuramıyla nasıl açıklanır?', 'Bant aralığı görünür ışık fotonlarının enerjisinden büyük olduğu için', ['Camda hiç elektron bulunmadığı için ışık etkileşmeden geçer.', 'Camın değerlik bandı ile iletim bandı örtüştüğü için ışık iletilir.', 'Cam ışığı ön yüzde soğurup aynı anda arka yüzden aynı dalga boyunda yeniden yayar.'], 'Camın bant aralığı büyüktür (yalıtkandır). Görünür ışığın fotonları elektronları iletim bandına çıkaracak enerjiye sahip olmadığından soğurulmaz ve cam saydam görünür.'),
  ('CH₄, SF₄ ve XeF₄ moleküllerinin üçü de AX₄ türünde dört bağlı atom içerir. Şekilleri için hangisi doğrudur?', 'Sırasıyla dörtyüzlü, tahterevalli ve kare düzlemdir.', ['Üçü de dörtyüzlüdür.', 'Üçü de kare düzlemdir.', 'Sırasıyla kare düzlem, dörtyüzlü ve tahterevalli şeklindedir.'], 'Şekli yalnız bağlı atom sayısı değil, ortaklanmamış çift sayısı da belirler. Merkez atomlarında sırasıyla 0, 1 ve 2 ortaklanmamış çift bulunur.'),
  ('Aşağıdaki taneciklerden hangisi doğrusal değildir?', 'SO₂', ['CO₂', 'N₃⁻', 'XeF₂'], 'CO₂ ve N₃⁻ iki elektron grubuna sahip, XeF₂ ise üç ortaklanmamış çifti ekvatorda olan doğrusal taneciklerdir. SO₂\'de kükürt bir ortaklanmamış çift taşır ve molekül açısaldır.'),
  ('Aşağıdaki moleküllerden hangisinde merkez atomun hibritleşmesi sp³d\'dir?', 'ClF₃', ['SF₆', 'BF₃', 'NH₃'], 'ClF₃\'te klorun çevresinde üç bağ ve iki ortaklanmamış çift olmak üzere beş elektron grubu vardır; bu sp³d\'ye karşılık gelir. SF₆ sp³d², BF₃ sp², NH₃ sp³\'tür.'),
  ('Aşağıdaki çiftlerden hangisindeki iki tanecik aynı molekül şekline sahiptir?', 'NH₃ ve H₃O⁺', ['BF₃ ve NF₃', 'CO₂ ve SO₂', 'CH₄ ve XeF₄'], 'NH₃ ve H₃O⁺ üç bağ ve bir ortaklanmamış çift taşır; ikisi de üçgen piramittir. Diğer çiftlerde ortaklanmamış çift sayısı farklı olduğundan şekiller farklıdır.'),
  ('Merkez atomunda ortaklanmamış çift bulunmayan tanecik hangisidir?', 'CO₃²⁻', ['SO₃²⁻', 'NH₃', 'H₂S'], 'Karbonatta karbon dört değerlik elektronunu ve iyon yükünü oksijenlerle bağlara harcar; ortaklanmamış çifti yoktur. Sülfit, amonyak ve H₂S\'nin merkez atomları ortaklanmamış çift taşır.'),
  ('Kükürt dioksidin O=S–O yapısında (her atom oktette) kükürt ve tekli bağlı oksijenin formal yükleri sırasıyla nedir?', '+1 ve −1', ['0 ve 0', '−1 ve +1', '+2 ve −2'], 'Kükürt: 6 − 2 − 3 = +1. Tekli bağlı oksijen: 6 − 6 − 1 = −1. İkili bağlı oksijen sıfır formal yük taşır; toplam yük sıfırdır.'),
  ('Florun bütün elementler içinde en tepkimeye yatkın olanlardan biri olmasının bağ enerjisi açısından iki nedeni hangisidir?', 'F–F bağının zayıf, florun kurduğu bağların ise çok güçlü olması', ['F–F bağının çok güçlü olması ve florun zayıf bağlar kurması', 'Florun soy gaz düzeninde bulunması ve bu yüzden elektron alamayıp hemen bağ kopartması', 'Flor atomlarının çok büyük olması ve bağ kuramaması'], 'F–F bağını koparmak için az enerji gerekir (yaklaşık 158 kJ/mol). Buna karşın H–F, C–F ve metal florürlerindeki bağlar çok güçlüdür; tepkimeler bu yüzden hem kolay başlar hem de çok ekzotermik olur.'),
  ('H₂O, NH₃ ve CH₄\'ün molar buharlaşma entalpileri büyükten küçüğe nasıl sıralanır?', 'H₂O > NH₃ > CH₄', ['CH₄ > NH₃ > H₂O', 'NH₃ > H₂O > CH₄', 'H₂O > CH₄ > NH₃'], 'Su molekül başına en çok hidrojen bağını kurar (yaklaşık 41 kJ/mol). Amonyağın hidrojen bağları daha zayıf ve azdır (yaklaşık 23 kJ/mol). Metan yalnız London kuvvetleriyle tutunur (yaklaşık 8 kJ/mol).'),
  ('Nilüfer yapraklarının üzerindeki su damlalarının yayılmadan yuvarlanıp kiri de alarak akması (lotus etkisi) hangi iki özelliğin birleşimiyle açıklanır?', 'Mumsu apolar yüzey ile yüzeydeki çok küçük pürüzler', ['Yaprak yüzeyinin suyla hidrojen bağı kurması ve düz olması', 'Yaprağın su moleküllerini iyonlarına ayırması', 'Yaprak yüzeyinin elektriksel olarak yüklü olması'], 'Mumsu, apolar yüzey suyla zayıf etkileşir; su damlası kohezyonla küre biçimini korur. Mikroskobik pürüzler damlanın yüzeye değme alanını daha da azaltır ve damla kolayca yuvarlanır.'),
  ('Karbon dioksit molekülündeki oksijen atomlarının hibritleşmesi genellikle hangisi olarak kabul edilir?', 'sp²', ['sp', 'sp³', 'sp³d'], 'Her oksijen bir C=O ikili bağı ve iki ortaklanmamış çift olmak üzere üç elektron grubu taşır. Üç grup sp² hibritleşmesine karşılık gelir; hibritleşmeye katılmayan p orbitali π bağını kurar.'),
  ('Na(g) atomunun iyonlaşma enerjisi +496 kJ/mol, Cl(g) atomunun elektron ilgisi −349 kJ/mol\'dür. Gaz hâlindeki Na ve Cl atomlarından gaz hâlinde Na⁺ ve Cl⁻ iyonları oluşturmanın net enerji değişimi kaç kJ/mol\'dür?', '+147', ['−147', '+845', '−845'], '496 + (−349) = +147 kJ/mol. Yalnız elektron aktarımı enerji ister; iyonik bileşiğin kararlılığı ancak iyonların örgüde bir araya gelmesiyle açığa çıkan örgü enerjisiyle sağlanır.'),
  ('Talkın Mohs sertlik ölçeğinde en yumuşak mineral (1) olmasının yapısal nedeni nedir?', 'Katmanların birbirine yalnız zayıf van der Waals kuvvetleriyle tutunması', ['Kristalinin yalnız metalik bağlar içermesi', 'Talkın oda sıcaklığında sıvı olması', 'Katmanlar arasında çok güçlü iyonik bağlar bulunması ve bunların kolayca kırılması'], 'Talkta her katman içinde güçlü Si–O ve Mg–O bağları vardır, ancak katmanlar yüksüzdür ve birbirine zayıf kuvvetlerle tutunur. Hafif bir kuvvet katmanları kaydırır; bu nedenle talk parmakla bile çizilebilir.'),
  ('Geçiş metali karbonillerinde sık kullanılan \'18 elektron kuralı\'na göre Ni(CO)₄\'teki nikel atomunun çevresinde kaç değerlik elektronu bulunur? (Ni: 10 değerlik elektronu; her CO 2 elektron verir)', '18', ['10', '14', '22'], 'Nikelin kendi 10 değerlik elektronuna dört CO ligandının her birinden gelen ikişer elektron eklenir: 10 + 4 × 2 = 18. Bu sayı geçiş metalleri için soy gaz düzenine karşılık gelir.'),
  ('Karbonik anhidraz enziminin etkin bölgesinde suyu bağlayıp CO₂\'nin suyla tepkimesini hızlandıran metal iyonu hangisidir?', 'Zn²⁺', ['Fe²⁺', 'Mg²⁺', 'Na⁺'], 'Karbonik anhidrazda Zn²⁺ iyonu üç histidin azotuna ve bir su molekülüne koordine olmuştur. Çinkoya bağlı su, protonunu kolayca vererek CO₂\'ye saldıran OH⁻\'ye dönüşür.'),
  ('DNA\'nın bir zincirindeki nükleotitleri birbirine bağlayan bağ ile iki zinciri bir arada tutan etkileşim için hangisi doğrudur?', 'Zincir içinde kovalent fosfodiester bağları, zincirler arasında hidrojen bağları', ['Zincir içinde hidrojen bağları, zincirler arasında kovalent bağlar', 'Her ikisi de sistein kalıntıları arasında kurulan disülfür köprüsüdür.', 'Zincir içinde ve zincirler arasında yalnız iyonik bağlar bulunur ve bunlar eşit güçtedir.'], 'Şeker-fosfat omurgası kovalent fosfodiester bağlarıyla kurulur ve çok sağlamdır. İki zincir ise bazlar arasındaki zayıf hidrojen bağlarıyla birleşir; bu sayede replikasyon sırasında kolayca ayrılabilir.'),
  ('Bir öğrenci \'Metallerde bağ elektronları, kovalent bağdaki gibi iki komşu atom arasında paylaşılır\' diyor. Bu ifade için hangisi doğrudur?', 'Yanlıştır; değerlik elektronları bütün kristale yayılmış hâldedir.', ['Doğrudur; metalik bağ, yönlü kovalent bağların toplamıdır.', 'Doğrudur; metal atomları birbirine elektron vererek iyon çiftleri oluşturur.', 'Yanlıştır; metallerde değerlik elektronu bulunmaz, yalnız iç elektronlar vardır.'], 'Metalik bağda değerlik elektronları belirli atom çiftlerine ait değildir; bütün kristal boyunca delokalizedir. Bu nedenle metalik bağ yönsüzdür ve metaller dövülebilir, iletkendir.'),
  ('Elmasta her karbon dört karbona bağlıdır ve her bağ iki atom tarafından paylaşılır. 1 mol elmasta kaç mol C–C bağı bulunur?', '2', ['4', '1', '8'], 'Her atom dört bağa katılır, ancak her bağ iki atom arasında ortaktır: 4 / 2 = 2. Dolayısıyla 1 mol elmasta 2 mol C–C bağı vardır.'),
  ('Kuvarsta (SiO₂) her silisyum dört oksijene bağlıdır. 1 mol SiO₂\'de kaç mol Si–O bağı bulunur?', '4', ['2', '1', '8'], 'Her Si atomu dört Si–O bağı kurar ve bu bağları sayarken yalnız silisyumları saymak yeterlidir; her bağın tek bir silisyumu vardır. 1 mol Si için 4 mol Si–O bağı bulunur.'),
  ('Buzda her su molekülü dört komşusuyla hidrojen bağına katılır. 1 mol buzda kaç mol hidrojen bağı vardır?', '2', ['4', '1', '8'], 'Her hidrojen bağı iki molekül tarafından paylaşılır: 4 / 2 = 2. Bu yüzden buzu tamamen buhar yapmak için kabaca mol başına iki hidrojen bağının kırılması gerekir.'),
  ('Oksijenin iki allotropu O₂ ve O₃ manyetik özellikleri bakımından karşılaştırıldığında hangisi doğrudur?', 'O₂ paramanyetik, O₃ diamanyetiktir.', ['İkisi de eşleşmemiş elektron taşıdığından paramanyetiktir.', 'O₂ diamanyetik, O₃ paramanyetiktir.', 'İkisi de diamanyetiktir.'], 'O₂\'de iki eşleşmemiş π* elektronu vardır. Ozonda 18 değerlik elektronunun tümü eşleşmiştir ve molekül diamanyetiktir.'),
  ('Buzda bir oksijene kovalent bağlı hidrojenin uzaklığı yaklaşık 100 pm, aynı hidrojenin komşu molekülün oksijenine uzaklığı ise yaklaşık 175 pm\'dir. Bu veriler neyi gösterir?', 'Hidrojen bağının kovalent bağdan daha uzun ve daha zayıf olduğunu', ['Hidrojenin iki oksijene eşit güçle bağlı olduğunu ve konumunun değişmediğini', 'Hidrojen bağının kovalent bağdan daha kısa olduğunu', 'Buzda hiç hidrojen bağı bulunmadığını'], 'Hidrojen kendi oksijenine kısa ve güçlü bir kovalent bağla, komşu oksijene ise daha uzun ve zayıf bir hidrojen bağıyla bağlıdır. Bu uzaklık yine de van der Waals temas uzaklığından kısadır; bu da özel bir çekimin varlığını gösterir.'),
  ('Su, etanol ve hekzanın oda sıcaklığındaki yüzey gerilimleri büyükten küçüğe nasıl sıralanır?', 'Su > etanol > hekzan', ['Hekzan > etanol > su', 'Etanol > su > hekzan', 'Su > hekzan > etanol'], 'Yüzey gerilimi moleküller arası çekimin gücünü yansıtır. Su güçlü ve çok sayıda hidrojen bağı, etanol daha az hidrojen bağı kurar; apolar hekzanda ise yalnız London kuvvetleri vardır.'),
  ('Bakır(II) sülfat çözeltisinin mavi görünmesinin nedeni hangisidir?', 'Hidratlı Cu²⁺ iyonunun turuncu-kırmızı ışığı soğurması', ['Cu²⁺ iyonlarının mavi ışık yayması', 'Sülfat iyonlarının mavi renkli olması', 'Suyun bakırla tepkimeye girip çözeltiden mavi renkli bir gaz çıkarması'], 'Su ligandlarıyla çevrili Cu²⁺ iyonunun d orbitalleri arasındaki enerji farkı turuncu-kırmızı ışığa karşılık gelir. Bu bölge soğurulunca göze tamamlayıcı renk olan mavi ulaşır.'),
  ('Kübik bor nitrür (borazon) elmastan sonra en sert maddelerden biridir. Bunun yapısal nedeni nedir?', 'B ve N atomlarının elmas benzeri kovalent ağ kurması', ['Bor nitrürün katmanlı yapısının kolayca kayması', 'Bor nitrürün metalik bağlı olması ve elektron denizinin örgüyü sertleştirmesi', 'Bor ve azot arasında yalnız zayıf London kuvvetleri bulunması'], 'Kübik BN\'de her bor dört azota, her azot dört bora dörtyüzlü düzende bağlanır. Bu düzen elmasınkine benzer ve çok sert bir kovalent ağ verir; borazon kesici takımlarda kullanılır.'),
  ('İnce tabaka kromatografisinde polar silika jel kullanıldığında, apolar bir çözücüyle yürütülen bir karışımda hangi bileşenin en kısa yol alması beklenir?', 'En polar bileşenin', ['En apolar bileşenin', 'En küçük moleküllü bileşenin', 'Bütün bileşenlerin aynı mesafeyi alması beklenir'], 'Polar bileşenler polar durgun faza hidrojen bağı ve dipol etkileşimleriyle daha güçlü tutunur. Apolar çözücü onları zor sürükler; bu nedenle en polar madde başlangıç çizgisine en yakın kalır.'),
  ('Hemoglobinin dört alt biriminin bir arada durmasında başlıca hangi etkileşimler rol oynar?', 'Alt birimler arasındaki hidrojen bağı, tuz köprüsü ve hidrofobik etkileşimler', ['Alt birimleri birbirine bağlayan peptit bağları', 'Alt birimler arasındaki metalik bağlar', 'Demir atomlarının alt birimler arasında kurduğu doğrudan Fe–Fe metal bağları'], 'Dört polipeptit zinciri ayrı ayrı sentezlenir ve kovalent bağla birleşmez. Yüzeylerindeki tamamlayıcı zayıf etkileşimler zincirleri dördüncül yapıda bir arada tutar; bu etkileşimlerin değişmesi oksijen bağlanmasını düzenler.'),
  ('Nişastaya iyot eklenince oluşan koyu mavi renk hangi etkileşimden kaynaklanır?', 'İyotun amiloz sarmalının içine yerleşip içerme kompleksi oluşturması', ['İyotun nişastadaki glikoz birimlerindeki –OH gruplarıyla kalıcı kovalent bağlar kurması', 'Nişastanın iyot tarafından yakılması', 'İyotun nişastayı iyonlarına ayırması'], 'Amiloz zinciri sarmal biçimde kıvrılır ve iç boşluğu apolardır. Polyiyodür zincirleri bu kanala dizilir; bu düzen görünür ışığı güçlü biçimde soğurur ve mavi-mor renk oluşur.'),
  ('Sisplatinin kanser hücrelerinde DNA\'ya bağlanması hangi bağ türüyle gerçekleşir?', 'Platinin guanin azotlarıyla koordine kovalent bağ kurması', ['Platinin DNA\'daki fosfat gruplarıyla metalik bağ kurması', 'Sisplatinin DNA ile yalnız zayıf London kuvvetleriyle etkileşip sarmalın arasına girmesi', 'Platin atomlarının DNA\'nın şekerleriyle iyonik bağ kurması'], 'Hücre içinde sisplatinin klor ligandları suyla yer değiştirir. Platin daha sonra komşu guaninlerin azot atomlarının ortaklanmamış çiftlerini alarak bağlanır; DNA bükülür ve hücre bölünmesi engellenir.'),
  ('Pirit (FeS₂, \'aptal altını\') kristalindeki anyon hangisidir?', 'Disülfür iyonu (S₂²⁻)', ['Sülfür iyonu (S²⁻)', 'S₈ halkası', 'Sülfat iyonu (SO₄²⁻)'], 'Piritte demir +2 yüklüdür ve iki kükürt atomu birbirine kovalent S–S bağıyla bağlanarak S₂²⁻ iyonunu oluşturur. Yapı, peroksit iyonu içeren bileşiklere benzer.'),
  ('Potasyum süperoksit (KO₂) katısı hangi iyonlardan oluşur?', 'K⁺ ve O₂⁻', ['K²⁺ ve O²⁻', 'K⁺ ve O²⁻', 'K⁺ ve O₂²⁻'], 'KO₂\'de potasyum her zamanki gibi +1 yüklüdür; bu yüzden anyon iki oksijenli ve −1 yüklü süperoksit iyonudur. Bu iyon bir eşleşmemiş elektron taşır ve KO₂ paramanyetiktir.'),
  ('16. grup hidrürlerinin (H₂Te, H₂Se, H₂S) kaynama noktalarındaki eğilim suya doğru uzatılırsa suyun yaklaşık −80 °C civarında kaynaması beklenir. Bu tahmin neyi gösterir?', 'Hidrojen bağları olmasaydı su oda koşullarında gaz olurdu.', ['Suyun kaynama noktasının yalnız molekül kütlesiyle açıklanabildiğini', 'Suyun kovalent bağlarının diğer hidrürlerden zayıf olduğunu', 'H₂S\'nin hidrojen bağı yaptığını'], 'Ağır üyelerden kütleye göre yapılan tahmin, suyun gerçek kaynama noktasından (100 °C) çok aşağıdadır. Aradaki büyük fark hidrojen bağlarının katkısıdır; bu bağlar olmasaydı yeryüzünde sıvı su bulunmazdı.'),
  ('Borik asit, B(OH)₃ moleküllerinin düzlemsel katmanlar oluşturduğu pul pul bir katıdır ve kayganlaştırıcı özelliği vardır. Katmanlar içindeki molekülleri bir arada tutan etkileşim hangisidir?', 'Hidrojen bağları', ['İyonik bağlar', 'Metalik bağlar', 'B–B kovalent bağları'], 'Her B(OH)₃ molekülünün –OH grupları komşu moleküllerin oksijenleriyle hidrojen bağı kurarak düzlemsel bir ağ oluşturur. Katmanlar ise birbirine zayıf kuvvetlerle tutunduğundan kolayca kayar.'),
  ('Sodyum ve potasyum ayrı ayrı oda sıcaklığında katı oldukları hâlde belirli oranlardaki NaK alaşımı oda sıcaklığında sıvıdır. Bunun yapısal açıklaması hangisidir?', 'Farklı büyüklükteki atomların düzenli bir örgüye iyi yerleşememesi', ['Alaşımda metalik bağın tamamen ortadan kalkması', 'Sodyum ile potasyumun alaşımda iyonik bağ yapması', 'Potasyum atomlarının sodyumdan daha küçük olup boşluklara girmesi ve örgüyü sertleştirmesi'], 'Na ve K atomlarının boyutları belirgin biçimde farklıdır. İki tür atom aynı örgüde düzenli istiflenemediğinden katı yapı kararsızlaşır ve karışımın erime noktası bileşenlerinkinin çok altına iner.'),
  ('Grafitte her karbon üç komşusuna bağlıdır. 1 mol grafitte yaklaşık kaç mol C–C bağı bulunur?', '1,5', ['3', '1', '2'], 'Her atom üç bağa katılır, her bağ iki atom tarafından paylaşılır: 3 / 2 = 1,5. Elmastaki 2 mol bağa göre daha az ama daha güçlü (kısmen ikili) bağlar vardır.'),
  ('Gıdalarda E385 koduyla katılan EDTA tuzlarının bir işlevi, eser metal iyonlarını bağlayarak yağların bozulmasını yavaşlatmaktır. Bu işlev hangi kimyasal özelliğe dayanır?', 'EDTA\'nın metal iyonlarını şelat olarak sıkıca sarması', ['EDTA\'nın yağlarla kovalent bağ kurması', 'EDTA\'nın gıdadaki oksijeni yakıp tüketmesi ve ortamı oksijensiz bırakması', 'EDTA\'nın gıdadaki suyu dondurması'], 'Demir ve bakır gibi metal iyonları yağların yükseltgenmesini hızlandırır. EDTA bu iyonları altı noktadan bağlayan kararlı şelatlara dönüştürerek etkisiz hâle getirir.'),
  ('Amonyağın eskiden beri endüstriyel soğutma sistemlerinde kullanılmasında hangi özelliği önemli rol oynar?', 'Hidrojen bağları nedeniyle buharlaşma ısısının yüksek olması', ['Apolar olup moleküller arası çekim göstermemesi ve bu yüzden hızla genleşmesi', 'Oda sıcaklığında katı olması', 'Buharlaşırken ısı açığa çıkarması'], 'Soğutucu akışkan buharlaşırken ortamdan ısı çeker. Amonyağın moleküller arası hidrojen bağları buharlaşma ısısını yüksek tuttuğundan birim kütle başına çok ısı taşıyabilir.'),
  ('Derişik sülfürik asidin sudan çok daha ağır, yağımsı bir akışkanlık göstermesinin başlıca nedeni nedir?', 'Molekülleri arasında yoğun bir hidrojen bağı ağı bulunması', ['Moleküllerinin apolar olması ve yalnız zayıf London kuvvetleriyle tutunması', 'Sülfürik asidin metalik bağ içermesi', 'Moleküllerinin birbirini itmesi'], 'H₂SO₄ molekülünde iki –OH grubu ve iki S=O oksijeni bulunur; bu gruplar komşu moleküllerle çok sayıda hidrojen bağı kurar. Moleküllerin birbirinin üzerinden kayması zorlaşır ve viskozite artar.'),
  ('Hidrojen peroksit (H₂O₂) yaklaşık 150 °C\'de, su ise 100 °C\'de kaynar. Bu farkı açıklayan en uygun ifade hangisidir?', 'H₂O₂ daha ağırdır ve en az su kadar hidrojen bağı kurabilir.', ['H₂O₂ molekülleri arasında hiç hidrojen bağı yoktur; yalnız London kuvvetleri vardır.', 'H₂O₂ iyonik bir bileşiktir.', 'Su molekülleri H₂O₂\'den daha fazla elektron içerir.'], 'H₂O₂\'de iki –OH grubu ve dört ortaklanmamış çift bulunur; hidrojen bağı ağı en az su kadar yoğundur. Ayrıca daha büyük kütlesi London kuvvetlerini artırır; bu yüzden daha yüksek sıcaklıkta kaynar.'),
  ('Zeolitlerin su yumuşatmada ve \'moleküler elek\' olarak kullanılmasını sağlayan yapısal özellik hangisidir?', 'Düzenli boyutta boşluklar içeren alüminosilikat ağ yapısı', ['Ayrık moleküllerden oluşan yumuşak, mumsu yapısı ve düşük erime noktası', 'Elektron denizi içeren metalik örgüsü', 'Oda sıcaklığında sıvı olması'], 'Zeolitler SiO₄ ve AlO₄ dörtyüzlülerinin oluşturduğu eksi yüklü bir ağdır. Ağdaki boşluklarda tutunan Na⁺ gibi iyonlar Ca²⁺ ile yer değiştirebilir; boşlukların belirli boyutu da yalnız belirli moleküllerin girmesine izin verir.'),
  ('F–H···F, O–H···O ve N–H···N hidrojen bağlarının tipik güçleri büyükten küçüğe nasıl sıralanır?', 'F–H···F > O–H···O > N–H···N', ['N–H···N > O–H···O > F–H···F', 'O–H···O > N–H···N > F–H···F', 'Üçü de eşit güçtedir.'], 'Hidrojene bağlı atom ne kadar elektronegatifse hidrojen o kadar kısmi artı yüklü olur ve alıcı çifte daha güçlü çekilir. Elektronegatiflik F > O > N sırasındadır.'),
  ('Molekül orbital kuramına göre iki atom orbitalinin etkili biçimde birleşebilmesi için hangi koşul gerekir?', 'Enerjilerinin yakın ve simetrilerinin uygun olması', ['İki orbitalin de tamamen boş olması ve elektronların sonradan eklenmesi', 'İki atomun aynı element olması', 'Orbitallerin birbirine dik konumda olması'], 'Enerjileri çok farklı orbitaller ya da örtüşmesi simetri nedeniyle sıfır olan orbitaller anlamlı bir molekül orbitali oluşturmaz. HF\'deki bağ yapmayan flor orbitalleri buna örnektir.'),
  ('Hidrojen bağlarının DNA çift sarmalının ısıtılınca iki zincire ayrılabilmesi (erimesi) açısından önemi nedir?', 'Zayıf oldukları için ısıyla kopup soğuyunca yeniden kurulmaları', ['Kovalent bağlar kadar güçlü olup hiç kopmamaları', 'Isıtılınca güçlenip zincirleri daha sıkı bağlamaları', 'DNA zincirleri arasında hiç bulunmamaları ve zincirlerin kovalent bağlarla tutunması'], 'Hidrojen bağları kovalent bağlardan çok zayıf olduğundan ılımlı ısıtma zincirleri ayırır, ama omurgadaki kovalent bağlar sağlam kalır. Soğutulunca tamamlayıcı zincirler yeniden eşleşir; PCR gibi yöntemler buna dayanır.'),
  ('Susuz kalsiyum klorür havada açık bırakıldığında havadaki nemi çekip zamanla kendi çektiği suda çözünür. Bu olaya ne ad verilir?', 'Erirlik (havada eriyip sıvılaşma)', ['Süblimleşme', 'Çiçeklenme (kristal suyunu kaybetme)', 'Polimerleşme'], 'Ca²⁺ iyonlarının su molekülleriyle güçlü iyon-dipol etkileşimi nedeniyle tuz havadaki nemi çok hızlı tutar. Sonunda tuz, çektiği suda çözünerek derişik bir çözelti oluşturur.'),
  ('Hidratlı kristallerin bir kısmının kuru havada kristal suyunu kendiliğinden kaybedip yüzeyde toz oluşturması olayına ne ad verilir?', 'Çiçeklenme', ['Erirlik', 'Süblimleşme', 'Yoğuşma'], 'Çamaşır sodası (Na₂CO₃·10H₂O) gibi bazı hidratlar, havadaki su buharı basıncı düşük olduğunda kristal suyunun bir kısmını havaya verir ve yüzeyleri beyaz bir toza dönüşür.'),
  ('Gaz hidratlarında (klatratlarda) kafes içine hangi tür moleküllerin girebileceğini en çok ne belirler?', 'Konuk molekülün boyutunun kafes boşluğuna uyması', ['Konuk molekülün suda iyonlaşabilmesi', 'Konuk molekülün metal olması', 'Konuk molekülün çok yüksek kaynama noktasına sahip olması'], 'Su molekülleri belirli büyüklükte çok yüzlü boşluklar kurar. Metan, CO₂, argon gibi küçük ve genellikle apolar moleküller bu boşluklara sığabildikleri ölçüde yerleşir; çok büyük moleküller giremez.'),
  ('Doğal gaz boru hatlarında soğuk ve yüksek basınçlı koşullarda katı tıkaçlar oluşabilmektedir. Bu tıkaçların yapısı en iyi nasıl tanımlanır?', 'Gazları hapseden buz benzeri gaz hidrat kristalleri', ['Metanın donarak oluşturduğu ve suyla hiç ilişkisi olmayan saf metan kristalleri', 'Borunun paslanmasıyla oluşan demir oksit', 'Metanın polimerleşmesiyle oluşan plastik'], 'Boru hattındaki su, yüksek basınç ve düşük sıcaklıkta hidrojen bağlı kafesler kurar ve gaz moleküllerini içine alır. Oluşan klatrat katısı akışı tıkayabilir; bu yüzden gaz kurutulur ya da önleyici kimyasallar eklenir.'),
  ('Halkalı olmayan (açık zincirli) bir molekülde σ bağı sayısı ile atom sayısı arasındaki ilişki hangisidir?', 'σ bağı sayısı, atom sayısının bir eksiğine eşittir.', ['σ bağı sayısı, atom sayısının iki katına eşittir.', 'σ bağı sayısı, atom sayısına eşittir.', 'σ bağı sayısı yalnız moleküldeki π bağı sayısına bağlıdır ve atom sayısından bağımsızdır.'], 'Açık zincirli bir molekülde her atomu diğerlerine bağlamak için atom sayısından bir eksik bağ gerekir ve her bağlantı tam bir σ bağı içerir. İkili ve üçlü bağlardaki fazladan bağlar π türündedir.'),
  ('Salisilik asitte –OH ve –COOH gruplarının benzen halkasında komşu konumlarda olması hangi etkileşime olanak verir?', 'Molekül içi hidrojen bağına', ['İki grup arasında iyonik bağa', 'İki grup arasında metalik bağa', 'Halkanın kopmasına'], 'Komşu –OH grubunun hidrojeni karboksil oksijenine yöneltilip altı üyeli bir halka kurar. Bu molekül içi hidrojen bağı salisilik asidin bazı fiziksel özelliklerini etkiler.'),
  ('H₂ (bağ enerjisi 436 kJ/mol, bağ uzunluğu 74 pm) ile Cl₂ (243 kJ/mol, 199 pm) için çizilen potansiyel enerji eğrileri karşılaştırıldığında hangisi doğrudur?', 'H₂\'nin minimumu hem daha derinde hem daha kısa uzaklıktadır.', ['Cl₂\'nin eğrisinin minimumu hem daha derinde hem de çok daha kısa uzaklıktadır.', 'İki eğrinin minimumu aynı derinlikte ve aynı uzaklıktadır.', 'H₂\'nin minimumu daha sığ ama daha uzun uzaklıktadır.'], 'Minimumun derinliği bağ enerjisini, minimumun konumu bağ uzunluğunu verir. H₂\'nin bağı hem daha güçlü hem daha kısadır.'),
  ('Bir molekülde atomlar bağ uzunluğuna karşılık gelen konumda sabit mi durur?', 'Hayır; denge uzaklığı çevresinde sürekli titreşirler.', ['Evet; mutlak sıfırın üstündeki her sıcaklıkta tamamen hareketsizdir.', 'Hayır; atomlar molekül içinde rastgele yer değiştirir.', 'Evet; ancak yalnız gaz hâlinde hareketsizdir.'], 'Bağ uzunluğu, atomların titreştiği konumların ortalamasıdır. Atomlar potansiyel enerji kuyusunun içinde ileri geri hareket eder; kızılötesi spektroskopi bu titreşimleri ölçer.'),
  ('N₂ ve CO izoelektroniktir ve bağ dereceleri aynıdır. Buna karşın CO\'nun bir dipol momenti varken N₂\'nin yoktur. Bunun nedeni nedir?', 'CO\'daki atomların farklı olup elektron yoğunluğunun simetrik dağılmaması', ['CO\'nun N₂\'den daha fazla elektron içermesi', 'N₂\'de π bağı bulunmaması', 'CO\'nun iyonik bir bileşik olması ve C⁺ ile O⁻ iyonlarından oluşan bir kristal kurması'], 'Elektron sayısı ve bağ düzeni aynı olsa da CO\'da çekirdek yükleri farklıdır (6 ve 8). Elektron bulutu iki atom arasında eşit paylaşılmaz; küçük de olsa bir dipol oluşur.'),
  ('SiO₄⁴⁻, PO₄³⁻, SO₄²⁻ ve ClO₄⁻ iyonları izoelektroniktir. Bu iyonların geometrisi için hangisi beklenir?', 'Dördü de dörtyüzlüdür.', ['Dördü de kare düzlemdir.', 'Yükleri farklı olduğu için geometrileri birbirinden farklıdır.', 'Yalnız ClO₄⁻ dörtyüzlü, diğerleri üçgen piramittir.'], 'Her birinde merkez atom dört oksijene bağlıdır ve ortaklanmamış çift taşımaz (toplam 32 değerlik elektronu). Aynı elektron düzeni aynı dörtyüzlü geometriyi verir.'),
  ('\'Merkez atomunda ortaklanmamış çift bulunan her molekül polardır\' ifadesine karşı örnek hangisidir?', 'XeF₂', ['NH₃', 'H₂O', 'SO₂'], 'XeF₂\'de ksenon üç ortaklanmamış çift taşır; ancak bu çiftler ekvatorda simetrik dağılır ve iki Xe–F dipolü 180°\'de birbirini götürür. Molekül apolardır. Diğer üç molekül polardır.'),
  ('Bir kovalent bağın heterolitik bölünerek iyonlar oluşturması hangi ortamda daha kolay gerçekleşir?', 'Oluşan iyonları sararak kararlı kılan polar bir çözücüde', ['Hiç molekül bulunmayan boşlukta', 'Apolar bir çözücüde, oluşan iyonlar çözücüden etkilenmeden yalnız kaldığında', 'Çok düşük sıcaklıktaki katı bir apolar ortamda'], 'Heterolitik bölünmede zıt yüklü iyonlar ayrılır; bu, gaz fazında çok enerji ister. Su gibi polar çözücüler iyonları iyon-dipol etkileşimiyle sarıp kararlı kıldığından bölünmeyi kolaylaştırır.'),
  ('Silika aerojeller katı oldukları hâlde son derece hafif ve çok iyi ısı yalıtkanıdır. Bunun yapısal nedeni nedir?', 'Hacminin çoğu hava dolu gözenekli ince bir SiO₂ ağı olması', ['Yoğun bir metalik örgüye sahip olması ve elektronların ısıyı yansıtması', 'Ayrık SiO₂ moleküllerinden oluşan bir sıvı olması', 'İçinde serbest elektronlar bulunması'], 'Aerojelde Si–O–Si bağlarıyla kurulmuş ince bir ağ, hacmin çok büyük kısmını kaplayan nano boyutlu gözenekleri çevreler. Katı iskelet çok az, gözenekler çok küçük olduğundan ısı iletimi son derece zayıftır.'),
  ('[Co(en)₃]³⁺ iyonunda kobalta üç etilendiamin (en) ligandı bağlıdır. Kobaltın koordinasyon sayısı kaçtır?', '6', ['3', '4', '9'], 'Koordinasyon sayısı ligand sayısına değil, metale bağlanan verici atom sayısına eşittir. Her etilendiamin iki azotuyla bağlandığından 3 × 2 = 6 olur.'),
  ('CO₂ oda koşullarında gaz, CS₂ ise sıvıdır (kaynama noktası 46 °C). İkisi de doğrusal ve apolar olduğuna göre bu fark nasıl açıklanır?', 'Büyük kükürt atomlarının London kuvvetlerini güçlendirmesi', ['CS₂ molekülleri arasında hidrojen bağı bulunması', 'CO₂\'nin iyonik bir bileşik olması', 'CS₂\'nin polar bir molekül olup dipol-dipol etkileşimi göstermesi'], 'Kükürt oksijenden çok daha büyük ve çok elektronludur; elektron bulutu kolay kutuplanır. Daha güçlü dağılma kuvvetleri CS₂\'yi oda sıcaklığında sıvı tutar.'),
  ('Etenin (C₂H₄) brom gibi maddelerle katılma tepkimesine girmesi sırasında ikili bağın hangi bileşeni kopar?', 'π bağı', ['σ bağı', 'Her iki bağ da kopar', 'Hiçbir bağ kopmaz'], 'İkili bağdaki π bağı σ bağından zayıftır ve elektronları bağ ekseninin dışında, daha erişilebilir bir bölgededir. Katılmada π bağı kopar; σ bağı korunur ve iki karbon tekli bağla bağlı kalır.'),
  ('Karbon elyafının (karbon fiber) çok yüksek çekme dayanımına sahip olmasının yapısal nedeni hangisidir?', 'Lif boyunca dizilmiş grafit benzeri katmanlardaki güçlü C–C bağları', ['Liflerde karbon atomlarının iyonik bağ kurması', 'Liflerin metalik bağlı karbondan oluşması', 'Lifler arasındaki zayıf London kuvvetlerinin çok sayıda olup kovalent bağdan güçlü hâle gelmesi'], 'Karbon elyafında grafit benzeri katmanlar lifin uzun ekseni boyunca hizalanmıştır. Çekme kuvveti bu yönde çok güçlü kovalent C–C bağlarına binerek lifin kopmasını zorlaştırır.'),
  ('Kükürt hekzaflorürde (SF₆) bütün S–F bağları polar olduğu hâlde molekülün dipol momenti sıfırdır. Bu, SF₆ ile ilgili hangi bilgiyi doğrular?', 'Altı bağın simetrik sekizyüzlü düzende karşılıklı durduğunu', ['Kükürdün iki ortaklanmamış çift taşıdığını', 'S–F bağlarının iyonik olduğunu ve iyonların birbirini tam olarak dengelediğini', 'Molekülün tahterevalli şeklinde olduğunu'], 'Sekizyüzlüde her S–F bağı tam karşısındaki bir başka S–F bağıyla 180° açı yapar. Üç çift bağ dipolü birbirini götürür ve net dipol sıfır olur.'),
  ('Erimiş kükürt soğuk suya dökülünce lastik gibi esneyen \'plastik kükürt\' elde edilir. Bu maddenin yapısı en iyi nasıl tanımlanır?', 'S₈ halkalarının açılmasıyla oluşan uzun Sₙ zincirleri', ['Kükürdün iyonlarına ayrılmasıyla oluşan iyonik kristal', 'S₂ moleküllerinden oluşan bir gaz', 'Elektron denizi içeren metalik kükürt'], 'Kükürt ısıtıldıkça S₈ halkaları açılır ve birbirine bağlanarak uzun zincirler oluşturur. Ani soğutma bu zincirleri düzensiz hâlde dondurur; zincirlerin birbirine dolanması lastiğe benzer esneklik verir. Zamanla madde yeniden rombik kükürde döner.'),
  ('C₆₀ fulleren molekülündeki karbon atomlarının hibritleşmesi en iyi hangisiyle tanımlanır?', 'sp²\'ye yakın', ['Tam sp³', 'sp', 'sp³d'], 'Her karbon üç komşu karbona bağlıdır ve π sisteminin bir parçasıdır. Küresel yüzey nedeniyle bağlar düzlemden biraz sapar; hibritleşme saf sp² ile sp³ arasında, sp²\'ye yakın kabul edilir.'),
  ('VSEPR kuramında karbon dioksitteki oksijen atomları üzerinde bulunan ortaklanmamış çiftler molekülün şeklini neden etkilemez?', 'Molekül şeklini yalnız merkez atom çevresindeki elektron grupları belirler.', ['Oksijen atomlarında hiç ortaklanmamış çift bulunmaz.', 'Ortaklanmamış çiftler her zaman şekli belirlemez, yalnız iyonlarda belirler.', 'Bu çiftler karbonla paylaşıldığı için bağ sayılır.'], 'Bir molekülün şekli merkez atoma bağlı atomların yönelimiyle tanımlanır. Bu yönelimi yalnız merkez atomun çevresindeki bağ ve çift grupları belirler; uç atomlardaki çiftler bağ açılarını değiştirmez.'),
  ('Sıvıların yüzeyinde bir \'zar\' varmış gibi davranılmasına yol açan yüzey gerilimi için doğru birim hangisidir?', 'J/m²', ['J/mol', 'Pa·s', 'Debye'], 'Yüzey gerilimi, yüzey alanını bir birim artırmak için gereken enerji ya da yüzey boyunca birim uzunluğa düşen kuvvettir. Bu nedenle J/m² ya da eşdeğeri N/m ile ifade edilir; Pa·s viskozitenin birimidir.'),
  ('BF₃, CO₃²⁻ ve NO₃⁻ taneciklerinin üçü de 24 değerlik elektronlu ve izoelektroniktir. Bunlar için hangisi beklenir?', 'Üçü de üçgen düzlem yapıdadır.', ['Üçü de üçgen piramittir.', 'Yalnız NO₃⁻ üçgen düzlem, diğerleri piramittir.', 'Üçü de doğrusaldır.'], 'Her birinde merkez atom üç atoma bağlıdır ve ortaklanmamış çift taşımaz. Aynı elektron düzeni aynı üçgen düzlem geometrisini verir.'),
  ('SO₂ ve O₃ molekülleri izoelektroniktir (18 değerlik elektronu). Bu iki molekül için hangisi doğrudur?', 'İkisi de açısaldır; merkez atomda bir ortaklanmamış çift vardır.', ['İkisi de doğrusaldır.', 'SO₂ doğrusal, O₃ açısaldır.', 'İkisi de üçgen düzlemdir ve merkez atomda ortaklanmamış çift bulunmaz.'], 'Her iki molekülde merkez atom iki atoma bağlıdır ve bir ortaklanmamış çift taşır; üç elektron grubu açısal bir şekil verir. Bağ açıları da benzerdir (yaklaşık 117–119°).'),
  ('Ozon tabakasında O₃ molekülleri morötesi ışığı soğurarak O₂ ve O atomuna ayrılır. Bu tepkimede O–O bağı nasıl kopar?', 'Homolitik olarak; iki parçaya birer elektron kalır', ['Heterolitik olarak; O⁺ ve O₂⁻ iyonları oluşur', 'Bağ kopmaz; molekül yalnızca dönme hareketini hızlandırır ve ısınır.', 'İyonik bağ olarak kopar ve iyon çifti oluşur'], 'Işıkla bağ kopması genellikle homolitiktir. Oluşan oksijen atomu eşleşmemiş elektronlar taşır ve hemen bir O₂ ile birleşerek yeniden ozon oluşturabilir; bu döngü morötesi ışığı ısıya dönüştürür.'),
  ('Bir öğrenci, iki maddeden birinin London kuvvetleriyle tutunduğu hâlde diğerinin hidrojen bağı yapmasına karşın daha yüksek kaynama noktasına sahip olduğunu görüyor. Bu durum hangi örnekle açıklanabilir?', 'Oktan (125 °C) ile metanol (65 °C)', ['Metan (−161 °C) ile su (100 °C)', 'Etan (−89 °C) ile etanol (78 °C)', 'Neon (−246 °C) ile amonyak (−33 °C)'], 'Oktan yalnız London kuvvetleriyle tutunur, ama büyük molekülü çok güçlü dağılma kuvvetleri oluşturur ve küçük, hidrojen bağlı metanolden daha yüksek sıcaklıkta kaynar. Diğer çiftlerde hidrojen bağlı madde daha yüksek kaynar.'),
  ('Pirincin elektrik iletkenliği saf bakırınkinden düşüktür. Bunun bağ açısından açıklaması hangisidir?', 'Farklı atomların örgüyü bozup elektronları daha çok saçması', ['Pirinçte hiç serbest elektron bulunmaması', 'Çinkonun bakırla iyonik bağ kurup elektronları tutması', 'Pirincin moleküler bir katı olması ve elektronların moleküllerde kalması'], 'Saf metalde düzenli örgü elektronların görece serbest ilerlemesine izin verir. Yabancı atomlar örgünün düzenini bozar; elektronlar bu düzensizliklerden saçılır ve direnç artar.'),
  ('Yakıtların yanmasıyla açığa çıkan enerjinin bağlar açısından kaynağı hangisidir?', 'Ürünlerde güçlü C=O ve O–H bağlarının oluşması', ['Yakıttaki bağların kırılırken enerji vermesi ve bu enerjinin ısıya dönüşmesi', 'Oksijen molekülünün yanarken kütle kaybetmesi', 'Yakıttaki atom çekirdeklerinin birleşmesi'], 'Yanmada yakıttaki C–H, C–C ve O=O bağları kırılır; bu enerji gerektirir. CO₂ ve H₂O\'daki çok güçlü C=O ve O–H bağlarının oluşumunda açığa çıkan enerji daha büyük olduğundan net olarak ısı açığa çıkar.'),
  ('Çikolatanın \'temperlenmesi\' sırasında kontrollü ısıtıp soğutmanın amacı nedir?', 'Kakao yağının istenen kristal biçiminde katılaşması', ['Çikolatadaki şekeri tamamen karamelleştirmek', 'Kakao yağının kovalent bağlarını koparıp daha küçük moleküllere ayırmak', 'Çikolatayı amorf bir cama dönüştürmek'], 'Kakao yağı birkaç farklı kristal biçiminde (polimorf) katılaşabilir. Temperleme, parlak, kırılınca çıtırdayan ve ağızda eriyen kararlı biçimin oluşmasını sağlar.'),
  ('Elektron denizi modeli, bant kuramıyla karşılaştırıldığında hangi gözlemi açıklamakta yetersiz kalır?', 'Bazı katıların yarı iletken, bazılarının yalıtkan olmasını', ['Metallerin elektriği iletmesini', 'Metallerin dövülüp ince levha hâline getirilebilmesini ve tel çekilebilmesini', 'Metallerin ısıyı iletmesini'], 'Elektron denizi modeli metallerin iletkenliğini ve dövülebilirliğini açıklar. Ancak bir katının neden yalıtkan ya da yarı iletken olduğunu, bant aralığı kavramını kullanan bant kuramı açıklar.'),
  ('Bir öğrenci \'Sıvı suda moleküller arası çekim olmasaydı su, kabın şeklini alamazdı\' diyor. Bu ifade için hangisi doğrudur?', 'Yanlıştır; çekim olmasaydı su sıvı değil gaz olurdu.', ['Doğrudur; kabın şeklini almak için güçlü çekim gerekir.', 'Doğrudur; gazlar da kabın şeklini alamaz.', 'Yanlıştır; su molekülleri zaten hiç birbirini çekmez.'], 'Moleküller arası çekim, molekülleri yoğun bir sıvı hâlinde bir arada tutar; bu çekim olmasaydı moleküller dağılır ve madde gaz olurdu. Kabın şeklini almak ise moleküllerin birbirinin üzerinden kayabilmesiyle ilgilidir.'),
];
